insert into public.journeys (id, ordinal, title, short_desc, long_desc, icon, color, level, cover_url, published) values
  ('memecoins', '1', 'Jornada de Memecoins', 'Aprenda a analisar memecoins do básico ao avançado.', 'Aprenda desde os fundamentos até estratégias mais avançadas para analisar e operar memecoins: como esses tokens funcionam, como ler market cap, liquidez e volume, como investigar contratos e holders, e como operar com processo e limites claros num dos cantos mais arriscados do mercado.', 'Rocket', 'mint', 'iniciante', '/journey-covers/memecoins.webp', true),
  ('futuros', '2', 'Jornada de Futuros', 'Domine contratos perpétuos, alavancagem e gestão de margem.', 'Entenda como funcionam os futuros perpétuos: long e short, alavancagem, margem, funding e liquidação. Aprenda a executar ordens com proteção, dimensionar posições e construir um plano de trade que sobreviva ao mercado mais implacável do cripto.', 'CandlestickChart', 'blue', 'intermediario', '/journey-covers/futuros.webp', true),
  ('trading', '3', 'Jornada de Trading', 'Construa a base do trading: leitura de gráfico, risco e rotina.', 'A base completa para operar qualquer mercado: leitura de candles, suporte e resistência, tendência e volume; indicadores usados com critério; gestão de risco de verdade; e a rotina — plano, diário e psicologia — que separa quem dura de quem desiste.', 'LineChart', 'lilac', 'iniciante', '/journey-covers/trading.webp', true)
