insert into public.lesson_content (lesson_id, content) values
  ('meme-m1l1', '{"paragraphs": ["O que são memecoins. Memecoins são tokens criados em torno de piadas, personagens ou momentos culturais da internet. Diferente de projetos com produto e receita, o valor delas vem quase totalmente de atenção, comunidade e narrativa. Quando a atenção cresce, o preço pode subir muito rápido. Quando a atenção acaba, o preço costuma cair na mesma velocidade.", "Isso não é um defeito escondido: é a natureza do ativo. A maioria das memecoins vai a zero, e algumas poucas capturam ciclos enormes de atenção. Por isso, quem opera esse mercado precisa tratar cada posição como capital de risco total. Nesta jornada, você vai aprender a ler os números por trás do hype, investigar tokens antes de comprar e operar com limites definidos. Comece assumindo o risco — e nunca o ignorando."], "takeaway": "Memecoin é um ativo movido a atenção e comunidade, não a fluxo de caixa — o risco faz parte da definição.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "O que diferencia uma memecoin de um token de utilidade?", "options": ["O blockchain onde foi criada", "O valor vem principalmente de atenção e comunidade, não de uso ou receita", "O preço unitário mais baixo", "A quantidade de holders"], "note": "Memecoin é um ativo movido a atenção e comunidade, não a fluxo de caixa — o risco faz parte da definição."}, "narration": {"src": "/audio/journeys/meme-m1l1.mp3", "captionsSrc": "/audio/journeys/meme-m1l1.json", "transcript": "O que são memecoins. Memecoins são tokens criados em torno de piadas, personagens ou momentos culturais da internet. Diferente de projetos com produto e receita, o valor delas vem quase totalmente de atenção, comunidade e narrativa. Quando a atenção cresce, o preço pode subir muito rápido. Quando a atenção acaba, o preço costuma cair na mesma velocidade.\n\nIsso não é um defeito escondido: é a natureza do ativo. A maioria das memecoins vai a zero, e algumas poucas capturam ciclos enormes de atenção. Por isso, quem opera esse mercado precisa tratar cada posição como capital de risco total. Nesta jornada, você vai aprender a ler os números por trás do hype, investigar tokens antes de comprar e operar com limites definidos. Comece assumindo o risco — e nunca o ignorando.", "summary": "O que define uma memecoin, por que elas existem e o papel da atenção nesse mercado.", "duration": 57.816, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m1l2', '{"paragraphs": ["Market cap e FDV. O preço unitário de um token não diz nada sozinho. Um token de um centavo pode ser mais caro que um de mil reais, dependendo de quantas unidades existem. A medida certa é o market cap: preço vezes as unidades em circulação. É ele que diz quanto o mercado está avaliando aquele token hoje.", "Já o FDV, valor totalmente diluído, considera todas as unidades que ainda podem entrar em circulação. Se o FDV é muito maior que o market cap, existe supply guardado que pode ser vendido no futuro — e isso pressiona o preço. Em memecoins, verifique sempre: quantas unidades existem, quantas circulam e quem segura a diferença. Um market cap pequeno sobe mais fácil, mas também é manipulado mais fácil. Os dois lados da mesma moeda."], "takeaway": "Compare tokens por market cap e FDV, nunca pelo preço unitário; supply que ainda vai destravar é diluição futura.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Um token custa R$ 0,0001 com 100 trilhões de unidades em circulação. O que isso diz sobre ele estar \"barato\"?", "options": ["Está barato, o preço é baixo", "Nada — barato ou caro depende do market cap, não do preço unitário", "Está caro, porque tem muito supply", "Depende só do volume"], "note": "Compare tokens por market cap e FDV, nunca pelo preço unitário; supply que ainda vai destravar é diluição futura."}, "narration": {"src": "/audio/journeys/meme-m1l2.mp3", "captionsSrc": "/audio/journeys/meme-m1l2.json", "transcript": "Market cap e FDV. O preço unitário de um token não diz nada sozinho. Um token de um centavo pode ser mais caro que um de mil reais, dependendo de quantas unidades existem. A medida certa é o market cap: preço vezes as unidades em circulação. É ele que diz quanto o mercado está avaliando aquele token hoje.\n\nJá o FDV, valor totalmente diluído, considera todas as unidades que ainda podem entrar em circulação. Se o FDV é muito maior que o market cap, existe supply guardado que pode ser vendido no futuro — e isso pressiona o preço. Em memecoins, verifique sempre: quantas unidades existem, quantas circulam e quem segura a diferença. Um market cap pequeno sobe mais fácil, mas também é manipulado mais fácil. Os dois lados da mesma moeda.", "summary": "Por que o preço unitário não diz nada e como ler market cap e fully diluted valuation.", "duration": 57.072, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m1l3', '{"paragraphs": ["Liquidez: o que sustenta o preço. Em memecoins, o preço que aparece na tela só vale se existir liquidez para você sair. A negociação acontece em pools: um cofre com dois ativos, o token e uma moeda base, como SOL ou uma stablecoin. Cada compra e venda move a proporção do pool — e move o preço.", "Quando o pool é pequeno, qualquer ordem relevante desloca o preço violentamente. Um token pode mostrar market cap de milhões com apenas alguns milhares de dólares de liquidez real. Nesse cenário, o número da tela é uma ficção: ninguém consegue sair por aquele valor. Antes de olhar gráfico, olhe o tamanho do pool, compare com o market cap e pergunte: se eu precisar vender agora, quem compra, e a que preço?"], "takeaway": "O preço só é real se houver liquidez para sair; avalie o tamanho do pool antes do gráfico.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Um token tem market cap de 10 milhões e pool de liquidez de 20 mil dólares. Qual o principal risco?", "options": ["Nenhum, o market cap é alto", "Vender qualquer posição relevante derruba o preço e você não sai pelo valor da tela", "O token pode ser clonado", "A taxa da DEX aumenta"], "note": "O preço só é real se houver liquidez para sair; avalie o tamanho do pool antes do gráfico."}, "narration": {"src": "/audio/journeys/meme-m1l3.mp3", "captionsSrc": "/audio/journeys/meme-m1l3.json", "transcript": "Liquidez: o que sustenta o preço. Em memecoins, o preço que aparece na tela só vale se existir liquidez para você sair. A negociação acontece em pools: um cofre com dois ativos, o token e uma moeda base, como SOL ou uma stablecoin. Cada compra e venda move a proporção do pool — e move o preço.\n\nQuando o pool é pequeno, qualquer ordem relevante desloca o preço violentamente. Um token pode mostrar market cap de milhões com apenas alguns milhares de dólares de liquidez real. Nesse cenário, o número da tela é uma ficção: ninguém consegue sair por aquele valor. Antes de olhar gráfico, olhe o tamanho do pool, compare com o market cap e pergunte: se eu precisar vender agora, quem compra, e a que preço?", "summary": "Como funcionam pools de liquidez e por que liquidez baixa transforma qualquer venda em desastre.", "duration": 52.08, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m1l4', '{"paragraphs": ["Volume e holders. Volume mostra quanto o token negociou num período — e, em teoria, quanta gente está participando. Mas em memecoins o volume pode ser fabricado: robôs comprando e vendendo entre as próprias carteiras para simular movimento. Isso se chama wash trading. Por isso, cruze o volume com outros dados: quantos traders únicos operaram, quantas carteiras novas chegaram, e se a liquidez acompanha o movimento.", "A contagem de holders também engana. Milhares de carteiras podem pertencer a uma pessoa só. Mais útil que o número total é a distribuição: quanto os maiores holders concentram e se essa concentração está caindo ou subindo. Nas próximas aulas você aprende a investigar isso na prática. Por enquanto, guarde a regra: número isolado não é evidência — consistência entre números é."], "takeaway": "Volume e holders podem ser fabricados; procure consistência entre volume, liquidez e número de traders reais.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Qual sinal levanta suspeita de volume artificial?", "options": ["Volume alto com liquidez e holders crescendo juntos", "Volume gigante com pouquíssimos traders únicos e liquidez parada", "Volume caindo em fim de semana", "Volume maior na DEX do que na CEX"], "note": "Volume e holders podem ser fabricados; procure consistência entre volume, liquidez e número de traders reais."}, "narration": {"src": "/audio/journeys/meme-m1l4.mp3", "captionsSrc": "/audio/journeys/meme-m1l4.json", "transcript": "Volume e holders. Volume mostra quanto o token negociou num período — e, em teoria, quanta gente está participando. Mas em memecoins o volume pode ser fabricado: robôs comprando e vendendo entre as próprias carteiras para simular movimento. Isso se chama wash trading. Por isso, cruze o volume com outros dados: quantos traders únicos operaram, quantas carteiras novas chegaram, e se a liquidez acompanha o movimento.\n\nA contagem de holders também engana. Milhares de carteiras podem pertencer a uma pessoa só. Mais útil que o número total é a distribuição: quanto os maiores holders concentram e se essa concentração está caindo ou subindo. Nas próximas aulas você aprende a investigar isso na prática. Por enquanto, guarde a regra: número isolado não é evidência — consistência entre números é.", "summary": "Como ler volume real, desconfiar de wash trading e interpretar a contagem de holders.", "duration": 57.12, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m1l5', '{"paragraphs": ["DEX e swaps. Memecoins nascem e vivem principalmente em corretoras descentralizadas, as DEXs. Ali não existe livro de ofertas como numa corretora tradicional: você negocia contra um pool de liquidez, usando um mecanismo chamado formador de mercado automático, o AMM. O preço é definido pela proporção entre os dois ativos do pool e se move a cada operação.", "Um swap é a troca direta: você envia um ativo e recebe outro, na mesma transação, direto da sua carteira. Isso traz autonomia — e responsabilidade. Não há suporte para desfazer erros. Nos swaps você vai encontrar dois custos: a taxa do pool e o slippage, a diferença entre o preço esperado e o executado. Entender esse mecanismo é pré-requisito para tudo que vem depois nesta jornada."], "takeaway": "Na DEX você negocia contra um pool, não contra outra pessoa; slippage e taxa fazem parte de todo swap.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Num swap em uma DEX com AMM, você negocia contra:", "options": ["Outro trader com ordem oposta", "A equipe do token", "Um pool de liquidez, com preço definido pela proporção dos ativos", "O validador da rede"], "note": "Na DEX você negocia contra um pool, não contra outra pessoa; slippage e taxa fazem parte de todo swap."}, "narration": {"src": "/audio/journeys/meme-m1l5.mp3", "captionsSrc": "/audio/journeys/meme-m1l5.json", "transcript": "DEX e swaps. Memecoins nascem e vivem principalmente em corretoras descentralizadas, as DEXs. Ali não existe livro de ofertas como numa corretora tradicional: você negocia contra um pool de liquidez, usando um mecanismo chamado formador de mercado automático, o AMM. O preço é definido pela proporção entre os dois ativos do pool e se move a cada operação.\n\nUm swap é a troca direta: você envia um ativo e recebe outro, na mesma transação, direto da sua carteira. Isso traz autonomia — e responsabilidade. Não há suporte para desfazer erros. Nos swaps você vai encontrar dois custos: a taxa do pool e o slippage, a diferença entre o preço esperado e o executado. Entender esse mecanismo é pré-requisito para tudo que vem depois nesta jornada.", "summary": "Como funciona uma corretora descentralizada, o que é um AMM e o que acontece num swap.", "duration": 54.912, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m2l1', '{"paragraphs": ["Como encontrar tokens. Milhares de memecoins são criadas todos os dias. Ferramentas de rastreamento, os screeners, mostram em tempo real o que está sendo lançado e negociado: liquidez, volume, idade do token, número de transações. O erro comum é usar essas listas como recomendação de compra. Elas são apenas um funil.", "Um filtro inicial razoável combina liquidez mínima real, algumas horas ou dias de vida, volume consistente e transações de compradores distintos. O que passa no filtro entra numa fila de investigação — contrato, liquidez, holders, comunidade — que você vai aprender nas próximas aulas. Quem compra direto da lista está apostando no escuro, junto com robôs mais rápidos. Quem investiga transforma o mesmo fluxo de novidade em vantagem de processo."], "takeaway": "Screener serve para filtrar, não para decidir; todo token encontrado entra numa fila de investigação, não de compra.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Qual é o uso correto de um screener de tokens?", "options": ["Comprar os primeiros da lista de alta", "Filtrar candidatos por liquidez, idade e volume para depois investigar cada um", "Copiar as compras das carteiras maiores", "Achar tokens antes de terem liquidez"], "note": "Screener serve para filtrar, não para decidir; todo token encontrado entra numa fila de investigação, não de compra."}, "narration": {"src": "/audio/journeys/meme-m2l1.mp3", "captionsSrc": "/audio/journeys/meme-m2l1.json", "transcript": "Como encontrar tokens. Milhares de memecoins são criadas todos os dias. Ferramentas de rastreamento, os screeners, mostram em tempo real o que está sendo lançado e negociado: liquidez, volume, idade do token, número de transações. O erro comum é usar essas listas como recomendação de compra. Elas são apenas um funil.\n\nUm filtro inicial razoável combina liquidez mínima real, algumas horas ou dias de vida, volume consistente e transações de compradores distintos. O que passa no filtro entra numa fila de investigação — contrato, liquidez, holders, comunidade — que você vai aprender nas próximas aulas. Quem compra direto da lista está apostando no escuro, junto com robôs mais rápidos. Quem investiga transforma o mesmo fluxo de novidade em vantagem de processo.", "summary": "Screeners, filtros úteis e como separar fluxo de novidade de ruído puro.", "duration": 57.024, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m2l2', '{"paragraphs": ["Como analisar liquidez e LP. Quem deposita os ativos que formam um pool recebe tokens de LP, que representam o direito de retirar essa liquidez. Aqui mora um dos maiores riscos das memecoins: se o criador guarda os tokens de LP, ele pode drenar o pool a qualquer momento — o famoso rug pull. A liquidez some e o token fica invendável.", "Por isso, verifique o destino do LP. Duas proteções comuns: o lock, que tranca os tokens de LP por um prazo num contrato de custódia, e o burn, que os envia para um endereço irrecuperável, tornando a liquidez permanente. Verifique também a proporção: um market cap alto sustentado por um pool minúsculo é castelo de areia. Liquidez travada não elimina outros golpes, mas fecha a porta de saída mais óbvia."], "takeaway": "Liquidez destravada é porta de saída para o criador; procure lock longo ou burn e proporção razoável entre pool e market cap.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "O que significa a liquidez de um pool estar \"queimada\"?", "options": ["O token perdeu valor", "Os tokens de LP foram enviados para um endereço irrecuperável, impedindo a remoção do pool", "O pool foi hackeado", "A taxa do pool subiu"], "note": "Liquidez destravada é porta de saída para o criador; procure lock longo ou burn e proporção razoável entre pool e market cap."}, "narration": {"src": "/audio/journeys/meme-m2l2.mp3", "captionsSrc": "/audio/journeys/meme-m2l2.json", "transcript": "Como analisar liquidez e LP. Quem deposita os ativos que formam um pool recebe tokens de LP, que representam o direito de retirar essa liquidez. Aqui mora um dos maiores riscos das memecoins: se o criador guarda os tokens de LP, ele pode drenar o pool a qualquer momento — o famoso rug pull. A liquidez some e o token fica invendável.\n\nPor isso, verifique o destino do LP. Duas proteções comuns: o lock, que tranca os tokens de LP por um prazo num contrato de custódia, e o burn, que os envia para um endereço irrecuperável, tornando a liquidez permanente. Verifique também a proporção: um market cap alto sustentado por um pool minúsculo é castelo de areia. Liquidez travada não elimina outros golpes, mas fecha a porta de saída mais óbvia.", "summary": "LP lock, burn de liquidez e a proporção saudável entre market cap e pool.", "duration": 55.032, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m2l3', '{"paragraphs": ["Contrato e permissões perigosas. Uma memecoin é um contrato, e o contrato faz o que o código manda — inclusive contra você. Quatro permissões merecem atenção. Primeira: mint, a capacidade de criar novas unidades e diluir todo mundo. Segunda: honeypot, quando o contrato deixa comprar mas bloqueia ou inviabiliza a venda. Terceira: blacklist, o poder de congelar carteiras específicas. Quarta: taxas modificáveis, que podem subir para noventa e nove por cento depois que você entrou.", "Ferramentas de auditoria automática detectam boa parte desses padrões em segundos — use mais de uma, porque nenhuma é infalível. Verifique também se a propriedade do contrato foi renunciada. Regra prática: se o criador mantém poderes que podem confiscar seu dinheiro, o risco não é de mercado, é de refém."], "takeaway": "Antes de comprar, cheque se o contrato permite mint, bloqueio de venda ou mudança de taxas — e se a propriedade foi renunciada.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "O que é um honeypot?", "options": ["Um token com taxa alta", "Um contrato que permite comprar, mas impede ou inviabiliza a venda", "Um pool sem liquidez", "Um token sem site"], "note": "Antes de comprar, cheque se o contrato permite mint, bloqueio de venda ou mudança de taxas — e se a propriedade foi renunciada."}, "narration": {"src": "/audio/journeys/meme-m2l3.mp3", "captionsSrc": "/audio/journeys/meme-m2l3.json", "transcript": "Contrato e permissões perigosas. Uma memecoin é um contrato, e o contrato faz o que o código manda — inclusive contra você. Quatro permissões merecem atenção. Primeira: mint, a capacidade de criar novas unidades e diluir todo mundo. Segunda: honeypot, quando o contrato deixa comprar mas bloqueia ou inviabiliza a venda. Terceira: blacklist, o poder de congelar carteiras específicas. Quarta: taxas modificáveis, que podem subir para noventa e nove por cento depois que você entrou.\n\nFerramentas de auditoria automática detectam boa parte desses padrões em segundos — use mais de uma, porque nenhuma é infalível. Verifique também se a propriedade do contrato foi renunciada. Regra prática: se o criador mantém poderes que podem confiscar seu dinheiro, o risco não é de mercado, é de refém.", "summary": "Honeypot, função de mint, blacklist e taxas modificáveis: o que um contrato pode fazer contra você.", "duration": 58.296, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m2l4', '{"paragraphs": ["Distribuição de holders e insiders. Depois do contrato, investigue quem segura o supply. Exploradores de blockchain mostram os maiores holders e o histórico de cada carteira. Sinais de alerta: poucas carteiras concentrando grande parte do supply, carteiras criadas na mesma hora e financiadas pela mesma origem, e snipers — robôs que compraram no primeiro segundo do lançamento, muitas vezes em lote, os chamados bundles.", "Quando um grupo conectado controla o supply, o gráfico é coreografia: eles seguram, o preço sobe, atraem compradores e despejam. Prefira distribuições em que os maiores holders têm fatias pequenas, o pool de liquidez é dos maiores endereços e a concentração cai com o tempo. Ler supply é menos glamouroso que ler gráfico — e evita muito mais prejuízo."], "takeaway": "Concentração alta em poucas carteiras conectadas é o padrão que antecede despejo; leia o supply antes do gráfico.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Os dez maiores holders de um token concentram 60% do supply e várias carteiras foram financiadas pela mesma origem. Isso indica:", "options": ["Comunidade forte", "Alto risco de controle por um grupo e despejo coordenado", "Liquidez saudável", "Token institucional"], "note": "Concentração alta em poucas carteiras conectadas é o padrão que antecede despejo; leia o supply antes do gráfico."}, "narration": {"src": "/audio/journeys/meme-m2l4.mp3", "captionsSrc": "/audio/journeys/meme-m2l4.json", "transcript": "Distribuição de holders e insiders. Depois do contrato, investigue quem segura o supply. Exploradores de blockchain mostram os maiores holders e o histórico de cada carteira. Sinais de alerta: poucas carteiras concentrando grande parte do supply, carteiras criadas na mesma hora e financiadas pela mesma origem, e snipers — robôs que compraram no primeiro segundo do lançamento, muitas vezes em lote, os chamados bundles.\n\nQuando um grupo conectado controla o supply, o gráfico é coreografia: eles seguram, o preço sobe, atraem compradores e despejam. Prefira distribuições em que os maiores holders têm fatias pequenas, o pool de liquidez é dos maiores endereços e a concentração cai com o tempo. Ler supply é menos glamouroso que ler gráfico — e evita muito mais prejuízo.", "summary": "Top holders, carteiras de insiders, snipers e bundles: como ler quem realmente controla o supply.", "duration": 54.648, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m2l5', '{"paragraphs": ["Comunidade e narrativa. Em memecoins, a comunidade é o produto. Mas engajamento se compra: bots inflam seguidores, grupos repetem as mesmas frases, influenciadores são pagos para postar sem avisar. O que não se compra facilmente é textura: conversa espontânea, piadas internas, gente discordando, memes novos surgindo sem pedido.", "Avalie também a narrativa. As memecoins que sobrevivem costumam capturar um momento cultural mais amplo — um personagem, um evento, um humor coletivo — e não apenas prometer valorização. Pergunte: essa piada faz sentido fora do grupo que a criou? Ela renderia semanas ou horas? E desconfie sempre do roteiro padrão de golpe: urgência, contagem regressiva e promessa de listagem iminente. Comunidade real convida; esquema empurra."], "takeaway": "Comunidade real conversa, cria e discorda; engajamento comprado só repete. Narrativa forte tem contexto cultural, não só promessa de alta.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Qual sinal sugere comunidade orgânica?", "options": ["Milhares de respostas idênticas com emojis de foguete", "Grupos com conversa real, piadas próprias, críticas e criadores de conteúdo espontâneos", "Seguidores comprados crescendo de mil em mil", "Promessa de listagem em corretora"], "note": "Comunidade real conversa, cria e discorda; engajamento comprado só repete. Narrativa forte tem contexto cultural, não só promessa de alta."}, "narration": {"src": "/audio/journeys/meme-m2l5.mp3", "captionsSrc": "/audio/journeys/meme-m2l5.json", "transcript": "Comunidade e narrativa. Em memecoins, a comunidade é o produto. Mas engajamento se compra: bots inflam seguidores, grupos repetem as mesmas frases, influenciadores são pagos para postar sem avisar. O que não se compra facilmente é textura: conversa espontânea, piadas internas, gente discordando, memes novos surgindo sem pedido.\n\nAvalie também a narrativa. As memecoins que sobrevivem costumam capturar um momento cultural mais amplo — um personagem, um evento, um humor coletivo — e não apenas prometer valorização. Pergunte: essa piada faz sentido fora do grupo que a criou? Ela renderia semanas ou horas? E desconfie sempre do roteiro padrão de golpe: urgência, contagem regressiva e promessa de listagem iminente. Comunidade real convida; esquema empurra.", "summary": "Como separar tração orgânica de engajamento comprado e avaliar a força de uma narrativa.", "duration": 58.752, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m3l1', '{"paragraphs": ["Ferramentas e preparo da carteira. Antes do primeiro swap, organize o ambiente. Regra número um: carteira dedicada. Operar memecoins na mesma carteira onde você guarda seu patrimônio é como levar todas as economias para um cassino. Crie uma carteira separada, transfira apenas o capital de risco e mantenha o principal em custódia própria, longe de qualquer contrato novo.", "Conheça suas ferramentas: a DEX ou o agregador que encontra a melhor rota de preço, o explorador da rede para conferir transações, e, se usar bots de execução, entenda que eles guardam sua chave — escolha com muito critério e mantenha pouco saldo. Revise e revogue aprovações de contratos periodicamente. Velocidade importa nesse mercado, mas sobrevivência importa mais. Preparo é o que separa operador de vítima."], "takeaway": "Opere memecoins com uma carteira separada e capital limitado; nunca use a carteira de custódia principal.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Por que usar uma carteira dedicada para memecoins?", "options": ["As taxas ficam menores", "Limita o dano de aprovações maliciosas e golpes ao capital de risco, protegendo o patrimônio principal", "O slippage diminui", "É exigência das DEXs"], "note": "Opere memecoins com uma carteira separada e capital limitado; nunca use a carteira de custódia principal."}, "narration": {"src": "/audio/journeys/meme-m3l1.mp3", "captionsSrc": "/audio/journeys/meme-m3l1.json", "transcript": "Ferramentas e preparo da carteira. Antes do primeiro swap, organize o ambiente. Regra número um: carteira dedicada. Operar memecoins na mesma carteira onde você guarda seu patrimônio é como levar todas as economias para um cassino. Crie uma carteira separada, transfira apenas o capital de risco e mantenha o principal em custódia própria, longe de qualquer contrato novo.\n\nConheça suas ferramentas: a DEX ou o agregador que encontra a melhor rota de preço, o explorador da rede para conferir transações, e, se usar bots de execução, entenda que eles guardam sua chave — escolha com muito critério e mantenha pouco saldo. Revise e revogue aprovações de contratos periodicamente. Velocidade importa nesse mercado, mas sobrevivência importa mais. Preparo é o que separa operador de vítima.", "summary": "Carteira dedicada, aprovações, bots de execução e higiene operacional antes do primeiro swap.", "duration": 56.16, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m3l2', '{"paragraphs": ["Entradas e saídas com plano. Em um mercado que se move em minutos, decidir na emoção é entregar dinheiro. O plano se escreve antes da compra e responde quatro perguntas. Por que entrar: qual é a tese — narrativa nova, distribuição saudável, atenção crescendo? Quanto entrar: uma fração pequena do capital de risco. Onde realizar: em memecoins, realização parcial é quase obrigatória — vender uma parte no primeiro múltiplo devolve o custo e deixa o resto correr sem ansiedade. Onde desistir: o ponto em que a tese morreu — liquidez saindo, insiders vendendo, atenção migrando.", "Depois de escrito, o plano se executa sem renegociação. O mercado vai testar sua disciplina com esperança na queda e ganância na alta. Quem sobrevive não é quem acerta mais: é quem erra pequeno e realiza de verdade."], "takeaway": "Escreva antes da compra: por que entrar, quanto, onde sair no lucro e no prejuízo — e execute realização parcial.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Qual prática melhora a consistência em memecoins?", "options": ["Comprar mais quando cai para baixar o preço médio", "Definir antes da entrada os pontos de realização parcial e de abandono da tese", "Segurar até voltar ao topo", "Entrar all-in em sinais de grupo"], "note": "Escreva antes da compra: por que entrar, quanto, onde sair no lucro e no prejuízo — e execute realização parcial."}, "narration": {"src": "/audio/journeys/meme-m3l2.mp3", "captionsSrc": "/audio/journeys/meme-m3l2.json", "transcript": "Entradas e saídas com plano. Em um mercado que se move em minutos, decidir na emoção é entregar dinheiro. O plano se escreve antes da compra e responde quatro perguntas. Por que entrar: qual é a tese — narrativa nova, distribuição saudável, atenção crescendo? Quanto entrar: uma fração pequena do capital de risco. Onde realizar: em memecoins, realização parcial é quase obrigatória — vender uma parte no primeiro múltiplo devolve o custo e deixa o resto correr sem ansiedade. Onde desistir: o ponto em que a tese morreu — liquidez saindo, insiders vendendo, atenção migrando.\n\nDepois de escrito, o plano se executa sem renegociação. O mercado vai testar sua disciplina com esperança na queda e ganância na alta. Quem sobrevive não é quem acerta mais: é quem erra pequeno e realiza de verdade.", "summary": "Definir tese, invalidação e realização parcial antes de comprar; por que a saída se decide antes da entrada.", "duration": 59.4, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m3l3', '{"paragraphs": ["Slippage, taxas e MEV. Todo swap tem custos além do preço. O slippage é a diferença entre o preço que você viu e o que executou — em pools rasos, ele explode. A tolerância de slippage é o limite que você aceita; alta demais, vira convite para abuso. Somam-se a taxa do pool, a taxa da rede e, em redes congestionadas, a taxa de prioridade para entrar no bloco.", "Existe ainda o MEV: robôs que observam as transações pendentes e lucram reordenando-as. O ataque clássico é o sandwich — o robô compra antes de você, sua ordem sobe o preço, ele vende em seguida. Sua perda, o lucro dele. Defesas práticas: tolerância mínima que execute, ordens menores, rotas de proteção contra MEV quando disponíveis. E atenção: token que só compra com slippage altíssimo costuma ser armadilha de taxa."], "takeaway": "Slippage alto demais convida ataque sandwich; use o mínimo que executa e desconfie de tokens que exigem tolerância enorme.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "O que é um ataque sandwich?", "options": ["Comprar em duas DEXs ao mesmo tempo", "Um robô compra antes da sua ordem e vende logo depois, empurrando seu preço de execução", "Dividir a ordem em três partes", "Uma taxa cobrada pela rede"], "note": "Slippage alto demais convida ataque sandwich; use o mínimo que executa e desconfie de tokens que exigem tolerância enorme."}, "narration": {"src": "/audio/journeys/meme-m3l3.mp3", "captionsSrc": "/audio/journeys/meme-m3l3.json", "transcript": "Slippage, taxas e MEV. Todo swap tem custos além do preço. O slippage é a diferença entre o preço que você viu e o que executou — em pools rasos, ele explode. A tolerância de slippage é o limite que você aceita; alta demais, vira convite para abuso. Somam-se a taxa do pool, a taxa da rede e, em redes congestionadas, a taxa de prioridade para entrar no bloco.\n\nExiste ainda o MEV: robôs que observam as transações pendentes e lucram reordenando-as. O ataque clássico é o sandwich — o robô compra antes de você, sua ordem sobe o preço, ele vende em seguida. Sua perda, o lucro dele. Defesas práticas: tolerância mínima que execute, ordens menores, rotas de proteção contra MEV quando disponíveis. E atenção: token que só compra com slippage altíssimo costuma ser armadilha de taxa.", "summary": "Os custos invisíveis de cada swap: tolerância de slippage, taxa de prioridade e ataques sandwich.", "duration": 61.128, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m3l4', '{"paragraphs": ["Gestão de posição e banca. A matemática das memecoins é brutal: a grande maioria vai a zero, e algumas poucas pagam múltiplos altos. A estrutura de banca precisa respeitar essa distribuição. Primeiro, isole o capital: um valor que você aceita perder por completo, separado do patrimônio e dos investimentos de longo prazo. Segundo, fatie: muitas posições pequenas sobrevivem à estatística; poucas posições grandes morrem com ela.", "Terceiro, ajuste a expectativa. O objetivo de uma posição individual não é acertar sempre — é perder pouco quando erra e deixar correr quando acerta, com realização parcial protegendo o custo. Nunca reponha banca no impulso após uma perda; isso tem nome, e se chama tilt. Revisite a banca em datas fixas, não em momentos de emoção. Processo primeiro, resultado depois."], "takeaway": "Posições pequenas e numerosas, banca isolada e a premissa de que qualquer token pode ir a zero a qualquer momento.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Qual estrutura de banca é coerente com memecoins?", "options": ["50% do patrimônio em um token promissor", "Capital de risco isolado, dividido em posições pequenas, assumindo que cada uma pode ir a zero", "Usar alavancagem para compensar posições pequenas", "Média a mercado sem limite"], "note": "Posições pequenas e numerosas, banca isolada e a premissa de que qualquer token pode ir a zero a qualquer momento."}, "narration": {"src": "/audio/journeys/meme-m3l4.mp3", "captionsSrc": "/audio/journeys/meme-m3l4.json", "transcript": "Gestão de posição e banca. A matemática das memecoins é brutal: a grande maioria vai a zero, e algumas poucas pagam múltiplos altos. A estrutura de banca precisa respeitar essa distribuição. Primeiro, isole o capital: um valor que você aceita perder por completo, separado do patrimônio e dos investimentos de longo prazo. Segundo, fatie: muitas posições pequenas sobrevivem à estatística; poucas posições grandes morrem com ela.\n\nTerceiro, ajuste a expectativa. O objetivo de uma posição individual não é acertar sempre — é perder pouco quando erra e deixar correr quando acerta, com realização parcial protegendo o custo. Nunca reponha banca no impulso após uma perda; isso tem nome, e se chama tilt. Revisite a banca em datas fixas, não em momentos de emoção. Processo primeiro, resultado depois.", "summary": "Tamanho de posição, banca separada e expectativa realista num mercado onde a maioria dos tokens vai a zero.", "duration": 60.48, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m4l1', '{"paragraphs": ["Rug pulls e soft rugs. O rug pull clássico é rápido: o criador retira a liquidez do pool e o token fica invendável em segundos. Você já sabe a defesa — liquidez travada ou queimada, verificada antes de entrar. Mas existe uma versão lenta e mais comum: o soft rug. A equipe não drena nada de uma vez; ela vende aos poucos as próprias reservas, deixa promessas vencerem, reduz a comunicação e abandona o projeto enquanto o gráfico sangra devagar.", "Os sinais aparecem on-chain antes do fim: carteiras da equipe transferindo para corretoras, supply de insiders diminuindo, liquidez encolhendo em silêncio. Monitorar as carteiras certas vale mais que qualquer promessa no grupo oficial. Quando os fundadores viram vendedores, a tese acabou — saia antes de precisar de esperança."], "takeaway": "Rug duro drena a liquidez de uma vez; soft rug mata por abandono e venda gradual dos insiders — os sinais aparecem on-chain antes.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "O que caracteriza um soft rug?", "options": ["A liquidez é drenada num bloco", "A equipe vende gradualmente e abandona o projeto enquanto mantém aparência de atividade", "O contrato bloqueia vendas", "A rede fica congestionada"], "note": "Rug duro drena a liquidez de uma vez; soft rug mata por abandono e venda gradual dos insiders — os sinais aparecem on-chain antes."}, "narration": {"src": "/audio/journeys/meme-m4l1.mp3", "captionsSrc": "/audio/journeys/meme-m4l1.json", "transcript": "Rug pulls e soft rugs. O rug pull clássico é rápido: o criador retira a liquidez do pool e o token fica invendável em segundos. Você já sabe a defesa — liquidez travada ou queimada, verificada antes de entrar. Mas existe uma versão lenta e mais comum: o soft rug. A equipe não drena nada de uma vez; ela vende aos poucos as próprias reservas, deixa promessas vencerem, reduz a comunicação e abandona o projeto enquanto o gráfico sangra devagar.\n\nOs sinais aparecem on-chain antes do fim: carteiras da equipe transferindo para corretoras, supply de insiders diminuindo, liquidez encolhendo em silêncio. Monitorar as carteiras certas vale mais que qualquer promessa no grupo oficial. Quando os fundadores viram vendedores, a tese acabou — saia antes de precisar de esperança.", "summary": "Anatomia do rug pull clássico e do abandono lento; sinais que antecedem cada um.", "duration": 55.296, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m4l2', '{"paragraphs": ["Golpes comuns fora do contrato. Nem todo golpe mora no código do token; muitos moram no clique. Sites clonados de DEXs capturam sua assinatura e drenam a carteira. Tokens-isca aparecem do nada no seu saldo e pedem resgate num site malicioso — a interação é o gatilho. Perfis falsos de projetos e influenciadores anunciam pré-vendas e mints que não existem. Suporte falso pede sua frase de recuperação, coisa que nenhum suporte legítimo jamais pede.", "As defesas são hábitos: digitar endereços conhecidos em vez de clicar em links, conferir o domínio letra por letra, ler o que cada assinatura autoriza antes de aprovar, revogar aprovações antigas com frequência e tratar qualquer urgência como bandeira vermelha. No cripto, a pressa é sempre do golpista."], "takeaway": "A maior parte das perdas vem de assinatura e aprovação dadas ao contrato errado; confira origem, domínio e o que exatamente você está assinando.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Você recebe um airdrop desconhecido que pede para \"resgatar\" num site. Qual a atitude correta?", "options": ["Resgatar rápido antes que expire", "Ignorar: interagir pode acionar aprovações que drenam a carteira", "Transferir o airdrop para a carteira principal", "Vender imediatamente na DEX"], "note": "A maior parte das perdas vem de assinatura e aprovação dadas ao contrato errado; confira origem, domínio e o que exatamente você está assinando."}, "narration": {"src": "/audio/journeys/meme-m4l2.mp3", "captionsSrc": "/audio/journeys/meme-m4l2.json", "transcript": "Golpes comuns fora do contrato. Nem todo golpe mora no código do token; muitos moram no clique. Sites clonados de DEXs capturam sua assinatura e drenam a carteira. Tokens-isca aparecem do nada no seu saldo e pedem resgate num site malicioso — a interação é o gatilho. Perfis falsos de projetos e influenciadores anunciam pré-vendas e mints que não existem. Suporte falso pede sua frase de recuperação, coisa que nenhum suporte legítimo jamais pede.\n\nAs defesas são hábitos: digitar endereços conhecidos em vez de clicar em links, conferir o domínio letra por letra, ler o que cada assinatura autoriza antes de aprovar, revogar aprovações antigas com frequência e tratar qualquer urgência como bandeira vermelha. No cripto, a pressa é sempre do golpista.", "summary": "Sites falsos, aprovações maliciosas, airdrops-isca, impersonação e engenharia social.", "duration": 53.688, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('meme-m4l3', '{"paragraphs": ["Checklist final do operador. Vamos consolidar a jornada numa rotina única. Antes de qualquer entrada: primeiro, o contrato — sem mint, sem honeypot, sem taxa modificável, propriedade renunciada. Segundo, a liquidez — travada ou queimada, com tamanho coerente com o market cap. Terceiro, o supply — sem concentração suspeita, sem bundles de snipers, insiders com fatias pequenas. Quarto, a comunidade — orgânica, com narrativa que se sustenta. Quinto, o plano — tese, tamanho, realização parcial e ponto de desistência escritos. Sexto, a banca — posição pequena, em carteira dedicada, com dinheiro que pode virar zero.", "Uma reprovação em qualquer etapa encerra a análise: o custo de perder uma oportunidade é sempre menor que o custo de ignorar um alerta. Disciplina não elimina o risco das memecoins — mas transforma aposta cega em risco calculado."], "takeaway": "Contrato, liquidez, holders, comunidade, plano e tamanho: se qualquer etapa falhar, a resposta padrão é não entrar.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Um token passa em tudo, exceto: o LP está destravado. O que fazer?", "options": ["Entrar com posição menor", "Não entrar — porta de saída aberta para o criador invalida o resto", "Entrar e monitorar o LP", "Esperar o preço cair"], "note": "Contrato, liquidez, holders, comunidade, plano e tamanho: se qualquer etapa falhar, a resposta padrão é não entrar."}, "narration": {"src": "/audio/journeys/meme-m4l3.mp3", "captionsSrc": "/audio/journeys/meme-m4l3.json", "transcript": "Checklist final do operador. Vamos consolidar a jornada numa rotina única. Antes de qualquer entrada: primeiro, o contrato — sem mint, sem honeypot, sem taxa modificável, propriedade renunciada. Segundo, a liquidez — travada ou queimada, com tamanho coerente com o market cap. Terceiro, o supply — sem concentração suspeita, sem bundles de snipers, insiders com fatias pequenas. Quarto, a comunidade — orgânica, com narrativa que se sustenta. Quinto, o plano — tese, tamanho, realização parcial e ponto de desistência escritos. Sexto, a banca — posição pequena, em carteira dedicada, com dinheiro que pode virar zero.\n\nUma reprovação em qualquer etapa encerra a análise: o custo de perder uma oportunidade é sempre menor que o custo de ignorar um alerta. Disciplina não elimina o risco das memecoins — mas transforma aposta cega em risco calculado.", "summary": "A rotina de verificação completa antes de qualquer entrada, consolidando toda a jornada.", "duration": 64.608, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('fut-m1l1', '{"paragraphs": ["O que são futuros perpétuos. Um contrato futuro é um derivativo: seu valor deriva do preço de um ativo, sem que você precise possuí-lo. Os futuros perpétuos, criados no mercado cripto, não têm data de vencimento — você pode manter a posição aberta enquanto tiver margem para sustentá-la. Para o preço do contrato não descolar do preço à vista, existe um mecanismo de ajuste chamado funding, que veremos adiante.", "A diferença crucial: no mercado à vista, o pior cenário é o ativo ir a zero. Nos futuros, com alavancagem, você pode perder toda a margem com um movimento pequeno na direção errada. É uma ferramenta profissional, com usos legítimos — especulação com capital eficiente e proteção de carteira — e um histórico enorme de contas zeradas por má gestão. Esta jornada existe para você ficar do lado certo dessa estatística."], "takeaway": "No perpétuo você opera um contrato indexado ao preço, sem vencimento e sem possuir o ativo — com riscos próprios que o spot não tem.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Qual a principal diferença entre comprar BTC à vista e abrir long em BTC perpétuo?", "options": ["Nenhuma, o preço é o mesmo", "No perpétuo você tem um contrato com margem, funding e risco de liquidação, sem possuir o ativo", "O perpétuo não tem taxas", "O spot é mais arriscado"], "note": "No perpétuo você opera um contrato indexado ao preço, sem vencimento e sem possuir o ativo — com riscos próprios que o spot não tem."}, "narration": {"src": "/audio/journeys/fut-m1l1.mp3", "captionsSrc": "/audio/journeys/fut-m1l1.json", "transcript": "O que são futuros perpétuos. Um contrato futuro é um derivativo: seu valor deriva do preço de um ativo, sem que você precise possuí-lo. Os futuros perpétuos, criados no mercado cripto, não têm data de vencimento — você pode manter a posição aberta enquanto tiver margem para sustentá-la. Para o preço do contrato não descolar do preço à vista, existe um mecanismo de ajuste chamado funding, que veremos adiante.\n\nA diferença crucial: no mercado à vista, o pior cenário é o ativo ir a zero. Nos futuros, com alavancagem, você pode perder toda a margem com um movimento pequeno na direção errada. É uma ferramenta profissional, com usos legítimos — especulação com capital eficiente e proteção de carteira — e um histórico enorme de contas zeradas por má gestão. Esta jornada existe para você ficar do lado certo dessa estatística.", "summary": "Derivativos, contratos perpétuos e a diferença entre operar o contrato e possuir o ativo.", "duration": 59.088, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('fut-m1l2', '{"paragraphs": ["Long e short na prática. Long é a aposta na alta: você compra o contrato e lucra se o preço subir. Short é a aposta na queda: você vende um contrato que não possui e lucra recomprando mais barato. Nos perpétuos, abrir short é tão simples quanto abrir long — um clique — mas o perfil de risco não é simétrico.", "No long, o pior caso do ativo é cair cem por cento. No short, o preço pode subir sem teto — e cada ponto de alta trabalha contra você, com o funding muitas vezes cobrando por cima. Por isso, shorts exigem ainda mais disciplina de stop. Um uso frequente e mais defensivo do short é o hedge: proteger uma carteira comprada sem precisar vendê-la, tema de aula futura. Direção é só metade da decisão; a outra metade, sempre, é o tamanho do risco."], "takeaway": "Long lucra na alta, short lucra na queda; o short tem risco assimétrico porque a alta não tem teto.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Por que o short tem perfil de risco diferente do long?", "options": ["Porque paga mais taxa", "Porque a queda é limitada a 100%, mas a alta contra o short não tem teto", "Porque a corretora limita shorts", "Não há diferença"], "note": "Long lucra na alta, short lucra na queda; o short tem risco assimétrico porque a alta não tem teto."}, "narration": {"src": "/audio/journeys/fut-m1l2.mp3", "captionsSrc": "/audio/journeys/fut-m1l2.json", "transcript": "Long e short na prática. Long é a aposta na alta: você compra o contrato e lucra se o preço subir. Short é a aposta na queda: você vende um contrato que não possui e lucra recomprando mais barato. Nos perpétuos, abrir short é tão simples quanto abrir long — um clique — mas o perfil de risco não é simétrico.\n\nNo long, o pior caso do ativo é cair cem por cento. No short, o preço pode subir sem teto — e cada ponto de alta trabalha contra você, com o funding muitas vezes cobrando por cima. Por isso, shorts exigem ainda mais disciplina de stop. Um uso frequente e mais defensivo do short é o hedge: proteger uma carteira comprada sem precisar vendê-la, tema de aula futura. Direção é só metade da decisão; a outra metade, sempre, é o tamanho do risco.", "summary": "Como funcionam as duas direções, o que significa vender o que não se tem e a simetria de riscos.", "duration": 56.76, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('fut-m1l3', '{"paragraphs": ["Alavancagem e margem. A margem é o valor que você deposita como garantia da posição. A alavancagem define quanta exposição essa margem controla: com dez vezes, mil reais controlam dez mil de posição. O detalhe que muda tudo: os ganhos e as perdas incidem sobre a posição inteira. Com dez vezes de alavancagem, um movimento de dez por cento contra você consome cem por cento da margem.", "Existem dois regimes. Na margem isolada, cada posição tem sua garantia própria: se der errado, você perde aquela margem e nada mais. Na margem cruzada, todo o saldo da conta sustenta todas as posições: mais resistência a oscilações, e o risco de uma posição ruim arrastar tudo. Para quem está construindo processo, isolada com alavancagem baixa é o ponto de partida sensato. Alavancagem não aumenta sua taxa de acerto — só o preço de cada erro."], "takeaway": "Alavancagem multiplica exposição, não acerto; margem isolada limita o dano por posição, cruzada arrisca a conta inteira.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Com 10x de alavancagem e margem isolada, aproximadamente que movimento contra a posição consome toda a margem?", "options": ["50%", "20%", "~10%", "1%"], "note": "Alavancagem multiplica exposição, não acerto; margem isolada limita o dano por posição, cruzada arrisca a conta inteira."}, "narration": {"src": "/audio/journeys/fut-m1l3.mp3", "captionsSrc": "/audio/journeys/fut-m1l3.json", "transcript": "Alavancagem e margem. A margem é o valor que você deposita como garantia da posição. A alavancagem define quanta exposição essa margem controla: com dez vezes, mil reais controlam dez mil de posição. O detalhe que muda tudo: os ganhos e as perdas incidem sobre a posição inteira. Com dez vezes de alavancagem, um movimento de dez por cento contra você consome cem por cento da margem.\n\nExistem dois regimes. Na margem isolada, cada posição tem sua garantia própria: se der errado, você perde aquela margem e nada mais. Na margem cruzada, todo o saldo da conta sustenta todas as posições: mais resistência a oscilações, e o risco de uma posição ruim arrastar tudo. Para quem está construindo processo, isolada com alavancagem baixa é o ponto de partida sensato. Alavancagem não aumenta sua taxa de acerto — só o preço de cada erro.", "summary": "Margem inicial e de manutenção, isolada versus cruzada, e o que a alavancagem realmente multiplica.", "duration": 62.232, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('fut-m1l4', '{"paragraphs": ["Funding rate e basis. Sem vencimento, o que impede o preço do perpétuo de descolar do preço à vista? O funding: um pagamento periódico entre traders. Quando o perpétuo negocia acima do spot — mercado comprado demais — quem está long paga quem está short, o que desestimula a euforia. Quando negocia abaixo, o fluxo se inverte. A diferença entre o perpétuo e o spot se chama basis.", "O funding é ao mesmo tempo um custo e um termômetro. Custo: manter posição contra o funding por semanas corrói o resultado em silêncio — some isso ao seu plano. Termômetro: funding extremo e persistente revela um lado do mercado lotado e alavancado, exatamente o cenário em que movimentos bruscos de correção, os squeezes, acontecem. Antes de abrir posição, olhe o funding. Ele conta o que a multidão está fazendo — e a multidão alavancada raramente termina bem."], "takeaway": "Funding positivo: longs pagam shorts; negativo: shorts pagam longs. Funding extremo revela desequilíbrio e custo real de carregar posição.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "O funding está fortemente positivo há dias. O que isso indica?", "options": ["O mercado está vendido e shorts pagam longs", "O mercado está comprado e alavancado; longs pagam para manter posição, sinal de euforia", "A corretora aumentou taxas", "Nada relevante"], "note": "Funding positivo: longs pagam shorts; negativo: shorts pagam longs. Funding extremo revela desequilíbrio e custo real de carregar posição."}, "narration": {"src": "/audio/journeys/fut-m1l4.mp3", "captionsSrc": "/audio/journeys/fut-m1l4.json", "transcript": "Funding rate e basis. Sem vencimento, o que impede o preço do perpétuo de descolar do preço à vista? O funding: um pagamento periódico entre traders. Quando o perpétuo negocia acima do spot — mercado comprado demais — quem está long paga quem está short, o que desestimula a euforia. Quando negocia abaixo, o fluxo se inverte. A diferença entre o perpétuo e o spot se chama basis.\n\nO funding é ao mesmo tempo um custo e um termômetro. Custo: manter posição contra o funding por semanas corrói o resultado em silêncio — some isso ao seu plano. Termômetro: funding extremo e persistente revela um lado do mercado lotado e alavancado, exatamente o cenário em que movimentos bruscos de correção, os squeezes, acontecem. Antes de abrir posição, olhe o funding. Ele conta o que a multidão está fazendo — e a multidão alavancada raramente termina bem.", "summary": "O mecanismo que ancora o perpétuo ao spot, quem paga quem e como ler o funding como termômetro.", "duration": 62.856, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('fut-m2l1', '{"paragraphs": ["Tipos de ordem nos futuros. As ordens são suas ferramentas de precisão. A ordem a mercado executa já, ao preço disponível — garantia de execução, nenhum controle de preço. A limitada define o preço máximo de compra ou mínimo de venda — controle total de preço, sem garantia de execução. O stop-market dispara uma ordem a mercado quando o preço atinge um gatilho: é o formato padrão da proteção de perda. O stop-limit dispara uma limitada — mais controle, e o risco real de não executar num movimento rápido, deixando você exposto exatamente quando mais precisava sair.", "Nos futuros existe ainda o reduce-only: uma trava que garante que a ordem apenas reduz a posição, nunca abre outra na direção contrária. Use em todo stop e todo alvo. Erro de ordem em mercado alavancado custa caro — automatize suas intenções."], "takeaway": "Ordem limitada controla preço, ordem a mercado garante execução; reduce-only garante que a proteção nunca vira posição nova.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Para que serve a opção reduce-only num stop?", "options": ["Reduzir a taxa da ordem", "Garantir que a ordem só diminua a posição existente, nunca abra uma nova na direção oposta", "Reduzir o slippage", "Reduzir a alavancagem"], "note": "Ordem limitada controla preço, ordem a mercado garante execução; reduce-only garante que a proteção nunca vira posição nova."}, "narration": {"src": "/audio/journeys/fut-m2l1.mp3", "captionsSrc": "/audio/journeys/fut-m2l1.json", "transcript": "Tipos de ordem nos futuros. As ordens são suas ferramentas de precisão. A ordem a mercado executa já, ao preço disponível — garantia de execução, nenhum controle de preço. A limitada define o preço máximo de compra ou mínimo de venda — controle total de preço, sem garantia de execução. O stop-market dispara uma ordem a mercado quando o preço atinge um gatilho: é o formato padrão da proteção de perda. O stop-limit dispara uma limitada — mais controle, e o risco real de não executar num movimento rápido, deixando você exposto exatamente quando mais precisava sair.\n\nNos futuros existe ainda o reduce-only: uma trava que garante que a ordem apenas reduz a posição, nunca abre outra na direção contrária. Use em todo stop e todo alvo. Erro de ordem em mercado alavancado custa caro — automatize suas intenções.", "summary": "Mercado, limitada, stop-market, stop-limit e reduce-only: quando usar cada uma.", "duration": 59.496, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('fut-m2l2', '{"paragraphs": ["Preço de marca e liquidação. Sua posição tem dois preços na tela. O último preço é o do negócio mais recente naquele livro — fácil de distorcer por um instante. O preço de marca é uma média composta com o preço à vista de várias fontes, mais resistente a manipulação. É ele que calcula seu lucro não realizado e, principalmente, sua liquidação.", "A liquidação acontece quando a margem da posição cai abaixo da margem de manutenção. A corretora encerra a posição à força, cobrando taxa punitiva; em movimentos violentos, o prejuízo pode passar da margem — e mecanismos como fundos de seguro entram em cena. Grave isto: liquidação não é stop. É o pior desfecho possível, com o pior preço e o maior custo. Conheça sempre seu preço de liquidação, mantenha-o longe do preço atual, e saia por decisão própria muito antes de a corretora decidir por você."], "takeaway": "A liquidação usa o preço de marca e consome sua margem com taxas punitivas; stop próprio existe para você nunca conhecê-la.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Por que as corretoras usam preço de marca em vez do último negócio para liquidar?", "options": ["Para lucrar mais", "Para evitar liquidações causadas por manipulação momentânea do último preço no próprio livro", "Porque é mais rápido", "Exigência regulatória"], "note": "A liquidação usa o preço de marca e consome sua margem com taxas punitivas; stop próprio existe para você nunca conhecê-la."}, "narration": {"src": "/audio/journeys/fut-m2l2.mp3", "captionsSrc": "/audio/journeys/fut-m2l2.json", "transcript": "Preço de marca e liquidação. Sua posição tem dois preços na tela. O último preço é o do negócio mais recente naquele livro — fácil de distorcer por um instante. O preço de marca é uma média composta com o preço à vista de várias fontes, mais resistente a manipulação. É ele que calcula seu lucro não realizado e, principalmente, sua liquidação.\n\nA liquidação acontece quando a margem da posição cai abaixo da margem de manutenção. A corretora encerra a posição à força, cobrando taxa punitiva; em movimentos violentos, o prejuízo pode passar da margem — e mecanismos como fundos de seguro entram em cena. Grave isto: liquidação não é stop. É o pior desfecho possível, com o pior preço e o maior custo. Conheça sempre seu preço de liquidação, mantenha-o longe do preço atual, e saia por decisão própria muito antes de a corretora decidir por você.", "summary": "Mark price versus last price, como a liquidação é calculada e por que ela não é um stop.", "duration": 62.28, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('fut-m2l3', '{"paragraphs": ["Stop, alvo e ordens combinadas. O stop não é um número aleatório de tolerância à dor — é o ponto em que sua análise se provou errada. Se você entrou porque um suporte segurou, o stop vai abaixo do suporte; perdeu o nível, a tese morreu, a posição fecha. O alvo segue a mesma lógica no lucro: definido pela estrutura do mercado, não pela vontade.", "As plataformas permitem anexar take profit e stop loss no momento da entrada, e ordens OCO — uma cancela a outra: bateu o alvo, o stop some; bateu o stop, o alvo some. Use esses recursos sempre, com reduce-only ativado. Posição alavancada sem stop na corretora é roleta com o mercado aberto vinte e quatro horas. E a regra de ouro: stop se move apenas a favor da posição, para proteger lucro. Alargar stop no prejuízo é a primeira parcela da liquidação."], "takeaway": "O stop fica onde a tese morre, não onde a dor aperta; alvo e stop entram junto com a posição, nunca depois.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Onde deve ficar o stop de uma operação?", "options": ["A uma distância fixa de 2% sempre", "No ponto em que a análise que motivou a entrada deixa de ser válida", "O mais longe possível para não ser ativado", "Não usar stop para evitar manipulação"], "note": "O stop fica onde a tese morre, não onde a dor aperta; alvo e stop entram junto com a posição, nunca depois."}, "narration": {"src": "/audio/journeys/fut-m2l3.mp3", "captionsSrc": "/audio/journeys/fut-m2l3.json", "transcript": "Stop, alvo e ordens combinadas. O stop não é um número aleatório de tolerância à dor — é o ponto em que sua análise se provou errada. Se você entrou porque um suporte segurou, o stop vai abaixo do suporte; perdeu o nível, a tese morreu, a posição fecha. O alvo segue a mesma lógica no lucro: definido pela estrutura do mercado, não pela vontade.\n\nAs plataformas permitem anexar take profit e stop loss no momento da entrada, e ordens OCO — uma cancela a outra: bateu o alvo, o stop some; bateu o stop, o alvo some. Use esses recursos sempre, com reduce-only ativado. Posição alavancada sem stop na corretora é roleta com o mercado aberto vinte e quatro horas. E a regra de ouro: stop se move apenas a favor da posição, para proteger lucro. Alargar stop no prejuízo é a primeira parcela da liquidação.", "summary": "Posicionar stop pela invalidação técnica, definir alvos e usar TP/SL e OCO para automatizar o plano.", "duration": 60.288, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('fut-m2l4', '{"paragraphs": ["Tamanho de posição e risco por trade. Aqui está a conta mais importante da jornada. Passo um: defina quanto da conta você arrisca por operação — um por cento é referência comum. Passo dois: meça a distância entre a entrada e o stop, em percentual. Passo três: o tamanho da posição é o risco em dinheiro dividido pela distância do stop. Exemplo: conta de dez mil, risco de um por cento, cem reais. Stop a quatro por cento da entrada. Cem dividido por quatro por cento: posição de dois mil e quinhentos.", "Note o que aconteceu: a alavancagem nem entrou na conta — ela é só o instrumento que permite abrir esse tamanho com menos margem. Quem começa pela alavancagem está dimensionando pelo ego. Quem começa pelo risco sobrevive a sequências de perda, que são estatisticamente inevitáveis. Dez perdas seguidas a um por cento machucam; a cinco por cento, praticamente encerram a conta."], "takeaway": "Primeiro o risco em dinheiro, depois a distância do stop, e só então o tamanho; a alavancagem é consequência, não ponto de partida.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Conta de 10.000, risco de 1% por trade, stop a 4% da entrada. Qual o tamanho correto da posição?", "options": ["10.000", "100", "2.500", "40.000"], "note": "Primeiro o risco em dinheiro, depois a distância do stop, e só então o tamanho; a alavancagem é consequência, não ponto de partida."}, "narration": {"src": "/audio/journeys/fut-m2l4.mp3", "captionsSrc": "/audio/journeys/fut-m2l4.json", "transcript": "Tamanho de posição e risco por trade. Aqui está a conta mais importante da jornada. Passo um: defina quanto da conta você arrisca por operação — um por cento é referência comum. Passo dois: meça a distância entre a entrada e o stop, em percentual. Passo três: o tamanho da posição é o risco em dinheiro dividido pela distância do stop. Exemplo: conta de dez mil, risco de um por cento, cem reais. Stop a quatro por cento da entrada. Cem dividido por quatro por cento: posição de dois mil e quinhentos.\n\nNote o que aconteceu: a alavancagem nem entrou na conta — ela é só o instrumento que permite abrir esse tamanho com menos margem. Quem começa pela alavancagem está dimensionando pelo ego. Quem começa pelo risco sobrevive a sequências de perda, que são estatisticamente inevitáveis. Dez perdas seguidas a um por cento machucam; a cinco por cento, praticamente encerram a conta.", "summary": "A fórmula que conecta risco percentual, distância do stop e tamanho da posição — e o papel real da alavancagem.", "duration": 65.232, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('fut-m3l1', '{"paragraphs": ["Contexto e padrões de mercado. Antes de qualquer entrada, classifique o ambiente. O mercado está em tendência, com topos e fundos progredindo na mesma direção, ou lateral, preso entre um teto e um piso? Padrões só funcionam dentro de contexto: comprar rompimento em lateralização estreita é armadilha frequente; comprar recuo em tendência de alta é operação com vento a favor.", "Nos futuros existe uma camada extra: o posicionamento alavancado. Zonas com grande concentração de liquidações funcionam como ímãs — o preço as visita, dispara stops em cascata e reverte. É o squeeze: no short squeeze, a alta força vendidos a recomprar, acelerando a própria alta. Funding extremo e open interest esticado avisam quando um lado está vulnerável. Combine estrutura de preço com posicionamento e você deixa de operar contra a máquina de caçar stops — e passa a operar com ela."], "takeaway": "Opere padrões apenas dentro de contexto favorável; em mercado alavancado, rompimentos falsos e squeezes são a regra, não a exceção.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "O que é um short squeeze?", "options": ["Uma queda lenta e contínua", "Alta rápida forçada pela liquidação em cascata de posições vendidas", "Um tipo de ordem", "Redução de taxas para shorts"], "note": "Opere padrões apenas dentro de contexto favorável; em mercado alavancado, rompimentos falsos e squeezes são a regra, não a exceção."}, "narration": {"src": "/audio/journeys/fut-m3l1.mp3", "captionsSrc": "/audio/journeys/fut-m3l1.json", "transcript": "Contexto e padrões de mercado. Antes de qualquer entrada, classifique o ambiente. O mercado está em tendência, com topos e fundos progredindo na mesma direção, ou lateral, preso entre um teto e um piso? Padrões só funcionam dentro de contexto: comprar rompimento em lateralização estreita é armadilha frequente; comprar recuo em tendência de alta é operação com vento a favor.\n\nNos futuros existe uma camada extra: o posicionamento alavancado. Zonas com grande concentração de liquidações funcionam como ímãs — o preço as visita, dispara stops em cascata e reverte. É o squeeze: no short squeeze, a alta força vendidos a recomprar, acelerando a própria alta. Funding extremo e open interest esticado avisam quando um lado está vulnerável. Combine estrutura de preço com posicionamento e você deixa de operar contra a máquina de caçar stops — e passa a operar com ela.", "summary": "Tendência versus lateralização, zonas de interesse, squeezes e como o contexto filtra suas operações.", "duration": 60.96, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('fut-m3l2', '{"paragraphs": ["Hedge com futuros. Nem todo short é aposta na queda: às vezes é seguro. Imagine que você mantém bitcoin em custódia própria com visão de longo prazo, mas espera turbulência de curto prazo e não quer vender. Um short perpétuo do mesmo tamanho neutraliza a oscilação: o que a carteira perde, o short ganha, e vice-versa.", "O seguro tem preço. Você imobiliza margem, paga ou recebe funding conforme o mercado, e assume risco operacional: um hedge mal dimensionado, ou liquidado por falta de margem, vira prejuízo em dobro. Por isso, hedge se calcula: tamanho equivalente à exposição, margem folgada, prazo definido e critério claro para desmontar. E seja honesto no diagnóstico: se a vontade de hedge é permanente, talvez a posição spot esteja simplesmente grande demais para o seu estômago — reduzir é o hedge mais barato que existe."], "takeaway": "Hedge troca risco de preço por custo de funding e risco operacional; é seguro temporário, não estratégia permanente.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Você tem 1 BTC em carteira própria e quer proteção para um evento de risco sem vender. O que faz sentido avaliar?", "options": ["Long alavancado em BTC", "Short de tamanho equivalente em BTC perpétuo, considerando custo de funding e margem", "Comprar uma memecoin", "Aumentar a alavancagem"], "note": "Hedge troca risco de preço por custo de funding e risco operacional; é seguro temporário, não estratégia permanente."}, "narration": {"src": "/audio/journeys/fut-m3l2.mp3", "captionsSrc": "/audio/journeys/fut-m3l2.json", "transcript": "Hedge com futuros. Nem todo short é aposta na queda: às vezes é seguro. Imagine que você mantém bitcoin em custódia própria com visão de longo prazo, mas espera turbulência de curto prazo e não quer vender. Um short perpétuo do mesmo tamanho neutraliza a oscilação: o que a carteira perde, o short ganha, e vice-versa.\n\nO seguro tem preço. Você imobiliza margem, paga ou recebe funding conforme o mercado, e assume risco operacional: um hedge mal dimensionado, ou liquidado por falta de margem, vira prejuízo em dobro. Por isso, hedge se calcula: tamanho equivalente à exposição, margem folgada, prazo definido e critério claro para desmontar. E seja honesto no diagnóstico: se a vontade de hedge é permanente, talvez a posição spot esteja simplesmente grande demais para o seu estômago — reduzir é o hedge mais barato que existe.", "summary": "Usar short perpétuo para proteger carteira spot: quando faz sentido, quanto custa e quais os limites.", "duration": 60.336, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('fut-m3l3', '{"paragraphs": ["Erros que liquidam contas. As contas raramente morrem por uma análise ruim — morrem por padrões de comportamento. Primeiro: overtrading, operar demais por tédio ou ansiedade, pagando taxa e funding para o mercado sem vantagem nenhuma. Segundo: martingale, dobrar o tamanho após perder para recuperar rápido — a matemática da ruína disfarçada de coragem. Terceiro: alavancagem por ego, dimensionar pela vontade de ganhar e não pelo risco aceitável. Quarto: remover ou alargar o stop no prejuízo, transformando um corte pequeno num desastre. Quinto: revenge trading, voltar ao mercado com raiva logo após uma perda, no exato momento em que seu julgamento está pior.", "A defesa é estrutural, não motivacional: limite diário de perda que fecha o dia, tamanho fixo por regra, stop na corretora e pausa obrigatória após sequência ruim. Disciplina que depende de força de vontade falha; disciplina automatizada sobrevive."], "takeaway": "Contas não morrem por uma análise errada, morrem por indisciplina repetida; reconheça os padrões em você antes que o extrato os mostre.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Após duas perdas seguidas, o trader dobra o tamanho para \"recuperar rápido\". Como se chama esse padrão e qual o resultado provável?", "options": ["Gestão agressiva; recuperação", "Martingale/revenge trading; risco crescente até a ruína", "Hedge dinâmico; neutro", "Scaling; lucro maior"], "note": "Contas não morrem por uma análise errada, morrem por indisciplina repetida; reconheça os padrões em você antes que o extrato os mostre."}, "narration": {"src": "/audio/journeys/fut-m3l3.mp3", "captionsSrc": "/audio/journeys/fut-m3l3.json", "transcript": "Erros que liquidam contas. As contas raramente morrem por uma análise ruim — morrem por padrões de comportamento. Primeiro: overtrading, operar demais por tédio ou ansiedade, pagando taxa e funding para o mercado sem vantagem nenhuma. Segundo: martingale, dobrar o tamanho após perder para recuperar rápido — a matemática da ruína disfarçada de coragem. Terceiro: alavancagem por ego, dimensionar pela vontade de ganhar e não pelo risco aceitável. Quarto: remover ou alargar o stop no prejuízo, transformando um corte pequeno num desastre. Quinto: revenge trading, voltar ao mercado com raiva logo após uma perda, no exato momento em que seu julgamento está pior.\n\nA defesa é estrutural, não motivacional: limite diário de perda que fecha o dia, tamanho fixo por regra, stop na corretora e pausa obrigatória após sequência ruim. Disciplina que depende de força de vontade falha; disciplina automatizada sobrevive.", "summary": "Os cinco padrões que destroem operadores de futuros: overtrading, martingale, alavancagem por ego, remoção de stop e revenge trading.", "duration": 65.064, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('fut-m3l4', '{"paragraphs": ["Plano de trade completo. Esta jornada termina onde o profissionalismo começa: num documento escrito. O plano define, primeiro, seus setups — as duas ou três situações específicas em que você tem permissão de operar, com gatilho, stop e alvo descritos. Segundo, o risco: percentual por operação, limite de perda diário e semanal, alavancagem máxima. Terceiro, a rotina: horários de análise, horários em que você não opera, checklist pré-entrada. Quarto, as métricas: registro de cada operação e revisão periódica de taxa de acerto, relação risco-retorno e erros de execução.", "E uma cláusula de pausa: o que o tira do mercado — sequência de perdas, limite atingido, estado emocional ruim. O mercado de futuros não perdoa improviso, mas recompensa consistência com juros compostos. Seu concorrente não é o mercado: é a sua versão sem plano."], "takeaway": "Se não está escrito, não é plano — é humor; opere apenas o que o documento autoriza e revise-o em datas fixas.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "O que um plano de trade minimamente completo contém?", "options": ["Apenas as moedas favoritas", "Setups permitidos, risco por trade, limite de perda, rotina e critérios de revisão", "Metas de lucro diário obrigatórias", "Os sinais de um grupo pago"], "note": "Se não está escrito, não é plano — é humor; opere apenas o que o documento autoriza e revise-o em datas fixas."}, "narration": {"src": "/audio/journeys/fut-m3l4.mp3", "captionsSrc": "/audio/journeys/fut-m3l4.json", "transcript": "Plano de trade completo. Esta jornada termina onde o profissionalismo começa: num documento escrito. O plano define, primeiro, seus setups — as duas ou três situações específicas em que você tem permissão de operar, com gatilho, stop e alvo descritos. Segundo, o risco: percentual por operação, limite de perda diário e semanal, alavancagem máxima. Terceiro, a rotina: horários de análise, horários em que você não opera, checklist pré-entrada. Quarto, as métricas: registro de cada operação e revisão periódica de taxa de acerto, relação risco-retorno e erros de execução.\n\nE uma cláusula de pausa: o que o tira do mercado — sequência de perdas, limite atingido, estado emocional ruim. O mercado de futuros não perdoa improviso, mas recompensa consistência com juros compostos. Seu concorrente não é o mercado: é a sua versão sem plano.", "summary": "O documento que integra tudo: setups, risco, rotina, métricas e critérios de pausa.", "duration": 63.504, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m1l1', '{"paragraphs": ["Candles e o que eles contam. Cada candle resume um período de negociação em quatro preços: abertura, máxima, mínima e fechamento. O corpo — a distância entre abertura e fechamento — mostra quem venceu o período: compradores, se fechou acima; vendedores, se fechou abaixo. Os pavios mostram até onde cada lado tentou ir e foi rejeitado.", "Um pavio inferior longo depois de uma queda conta uma história: vendedores empurraram, compradores compraram tudo e devolveram o preço para cima. Corpos grandes indicam convicção; corpos minúsculos com pavios dos dois lados indicam indecisão. Mas atenção ao erro clássico do iniciante: decorar nomes de padrões e aplicá-los isolados. Um candle só significa algo no lugar onde aparece — perto de que nível, dentro de qual tendência. Nas próximas aulas, construímos exatamente esse contexto."], "takeaway": "Candle é registro de batalha: corpo mostra quem venceu, pavios mostram onde houve rejeição — sempre leia no contexto, nunca isolado.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Um candle com pavio inferior longo e corpo pequeno no topo, após uma queda, sugere:", "options": ["Continuação da queda", "Compradores rejeitaram preços mais baixos; possível exaustão vendedora", "Nada, pavios são aleatórios", "Aumento de taxa"], "note": "Candle é registro de batalha: corpo mostra quem venceu, pavios mostram onde houve rejeição — sempre leia no contexto, nunca isolado."}, "narration": {"src": "/audio/journeys/trd-m1l1.mp3", "captionsSrc": "/audio/journeys/trd-m1l1.json", "transcript": "Candles e o que eles contam. Cada candle resume um período de negociação em quatro preços: abertura, máxima, mínima e fechamento. O corpo — a distância entre abertura e fechamento — mostra quem venceu o período: compradores, se fechou acima; vendedores, se fechou abaixo. Os pavios mostram até onde cada lado tentou ir e foi rejeitado.\n\nUm pavio inferior longo depois de uma queda conta uma história: vendedores empurraram, compradores compraram tudo e devolveram o preço para cima. Corpos grandes indicam convicção; corpos minúsculos com pavios dos dois lados indicam indecisão. Mas atenção ao erro clássico do iniciante: decorar nomes de padrões e aplicá-los isolados. Um candle só significa algo no lugar onde aparece — perto de que nível, dentro de qual tendência. Nas próximas aulas, construímos exatamente esse contexto.", "summary": "Anatomia do candle, o que corpo e pavios revelam sobre a batalha entre compradores e vendedores.", "duration": 60.432, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m1l2', '{"paragraphs": ["Suporte e resistência. Suporte é uma zona de preço onde a compra historicamente superou a venda, segurando quedas. Resistência é o espelho: uma zona onde a venda superou a compra, travando altas. Esses níveis funcionam porque têm memória — traders lembram de onde compraram, onde se arrependeram, onde há ordens acumuladas — e porque muita gente age sobre eles ao mesmo tempo.", "Trate-os como zonas, não como linhas milimétricas: o preço respeita regiões. Para mapear, procure pontos onde o preço reverteu mais de uma vez, e priorize os tempos gráficos maiores, onde os níveis são mais respeitados. Um comportamento clássico: suporte rompido tende a virar resistência, e resistência rompida tende a virar suporte — a memória do mercado troca de lado. Com o mapa de zonas pronto, você deixa de operar no meio do nada e passa a agir onde a reação é provável."], "takeaway": "Suporte e resistência são zonas, não linhas exatas; a reação do preço na zona vale mais que a zona em si.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Um suporte é rompido com força. O que costuma acontecer com esse nível?", "options": ["Deixa de importar", "Tende a virar resistência quando o preço retorna a ele", "Vira suporte mais forte", "O gráfico é invalidado"], "note": "Suporte e resistência são zonas, não linhas exatas; a reação do preço na zona vale mais que a zona em si."}, "narration": {"src": "/audio/journeys/trd-m1l2.mp3", "captionsSrc": "/audio/journeys/trd-m1l2.json", "transcript": "Suporte e resistência. Suporte é uma zona de preço onde a compra historicamente superou a venda, segurando quedas. Resistência é o espelho: uma zona onde a venda superou a compra, travando altas. Esses níveis funcionam porque têm memória — traders lembram de onde compraram, onde se arrependeram, onde há ordens acumuladas — e porque muita gente age sobre eles ao mesmo tempo.\n\nTrate-os como zonas, não como linhas milimétricas: o preço respeita regiões. Para mapear, procure pontos onde o preço reverteu mais de uma vez, e priorize os tempos gráficos maiores, onde os níveis são mais respeitados. Um comportamento clássico: suporte rompido tende a virar resistência, e resistência rompida tende a virar suporte — a memória do mercado troca de lado. Com o mapa de zonas pronto, você deixa de operar no meio do nada e passa a agir onde a reação é provável.", "summary": "Como identificar zonas onde o preço reage, por que funcionam e como usá-las como mapa.", "duration": 60.456, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m1l3', '{"paragraphs": ["Tendência e estrutura de mercado. Tire os indicadores da tela por um momento: tendência se lê na estrutura. Alta é uma escada de topos e fundos ascendentes — cada avanço supera o topo anterior, cada recuo para acima do fundo anterior. Baixa é a escada invertida. Quando topos e fundos se embaralham sem progressão, o mercado está lateral, e a maioria das estratégias de tendência perde dinheiro nele.", "A tendência permanece válida até a estrutura quebrar: numa alta, o alerta é o preço perder o último fundo relevante. Essa quebra de estrutura é o primeiro sinal objetivo de mudança — muito antes de qualquer indicador cruzar. A regra de sobrevivência do iniciante é simples: opere a favor da tendência do tempo gráfico em que analisa, e recuos dentro dela são as oportunidades de maior probabilidade. Prever reversões parece inteligente; acompanhar tendências paga as contas."], "takeaway": "Tendência de alta = topos e fundos ascendentes; ela vale até a estrutura quebrar. Operar contra tendência é pagar para nadar contra a maré.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "O que caracteriza uma tendência de alta?", "options": ["Preço acima da média de 200", "Sequência de topos e fundos ascendentes", "Volume alto", "RSI acima de 50"], "note": "Tendência de alta = topos e fundos ascendentes; ela vale até a estrutura quebrar. Operar contra tendência é pagar para nadar contra a maré."}, "narration": {"src": "/audio/journeys/trd-m1l3.mp3", "captionsSrc": "/audio/journeys/trd-m1l3.json", "transcript": "Tendência e estrutura de mercado. Tire os indicadores da tela por um momento: tendência se lê na estrutura. Alta é uma escada de topos e fundos ascendentes — cada avanço supera o topo anterior, cada recuo para acima do fundo anterior. Baixa é a escada invertida. Quando topos e fundos se embaralham sem progressão, o mercado está lateral, e a maioria das estratégias de tendência perde dinheiro nele.\n\nA tendência permanece válida até a estrutura quebrar: numa alta, o alerta é o preço perder o último fundo relevante. Essa quebra de estrutura é o primeiro sinal objetivo de mudança — muito antes de qualquer indicador cruzar. A regra de sobrevivência do iniciante é simples: opere a favor da tendência do tempo gráfico em que analisa, e recuos dentro dela são as oportunidades de maior probabilidade. Prever reversões parece inteligente; acompanhar tendências paga as contas.", "summary": "Topos e fundos ascendentes ou descendentes, quebra de estrutura e a regra de operar a favor.", "duration": 60.576, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m1l4', '{"paragraphs": ["Volume como confirmação. O preço diz o que aconteceu; o volume diz quanta gente participou — e movimentos sem participação merecem desconfiança. A leitura básica: numa tendência saudável, o volume cresce nos impulsos a favor e seca nos recuos. Quando um impulso avança com volume cada vez menor, a convicção está evaporando, mesmo que o preço ainda suba.", "O uso mais prático é validar rompimentos. Romper uma resistência exige absorver vendedores; isso consome volume. Um rompimento com volume bem acima da média tem lastro. Um rompimento silencioso, com volume fraco, frequentemente é armadilha: o preço fura o nível, atrai compradores atrasados e devolve — o falso rompimento. Volume não é gatilho de entrada sozinho; é o detector de mentiras do gráfico. Preço propõe, volume confirma."], "takeaway": "Movimento com volume tem participação real; rompimento sem volume é suspeito por padrão.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "O preço rompe uma resistência importante com volume muito abaixo da média. Como interpretar?", "options": ["Rompimento confiável", "Rompimento suspeito, com risco elevado de ser falso", "Sinal de venda imediata", "O volume não importa em rompimentos"], "note": "Movimento com volume tem participação real; rompimento sem volume é suspeito por padrão."}, "narration": {"src": "/audio/journeys/trd-m1l4.mp3", "captionsSrc": "/audio/journeys/trd-m1l4.json", "transcript": "Volume como confirmação. O preço diz o que aconteceu; o volume diz quanta gente participou — e movimentos sem participação merecem desconfiança. A leitura básica: numa tendência saudável, o volume cresce nos impulsos a favor e seca nos recuos. Quando um impulso avança com volume cada vez menor, a convicção está evaporando, mesmo que o preço ainda suba.\n\nO uso mais prático é validar rompimentos. Romper uma resistência exige absorver vendedores; isso consome volume. Um rompimento com volume bem acima da média tem lastro. Um rompimento silencioso, com volume fraco, frequentemente é armadilha: o preço fura o nível, atrai compradores atrasados e devolve — o falso rompimento. Volume não é gatilho de entrada sozinho; é o detector de mentiras do gráfico. Preço propõe, volume confirma.", "summary": "Como o volume valida ou desmente movimentos de preço; divergências e rompimentos sem participação.", "duration": 59.808, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m2l1', '{"paragraphs": ["Médias móveis. A média móvel suaviza o ruído: em vez de cada candle, você vê o preço médio dos últimos períodos deslizando pelo gráfico. A simples pesa todos os períodos igualmente; a exponencial dá mais peso ao recente e reage mais rápido. Períodos curtos, como vinte e um, acompanham o movimento de perto; longos, como duzentos, mostram a maré de fundo — preço acima da média longa sugere ambiente comprador, abaixo, vendedor.", "Em tendências, médias funcionam como suporte e resistência dinâmicos: o preço recua até elas e reage, oferecendo pontos de interesse objetivos. Mas entenda a limitação de fábrica: toda média é calculada sobre o passado e sempre atrasa. Em mercado lateral, ela serpenteia pelo meio do preço e gera sinal falso atrás de sinal falso. Média móvel é régua de contexto, não botão de compra — combine-a com a estrutura que você aprendeu no módulo um."], "takeaway": "Média móvel resume a tendência e serve de referência dinâmica; ela atrasa por construção e falha em mercado lateral.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Qual a limitação estrutural de toda média móvel?", "options": ["Só funciona em cripto", "É calculada sobre o passado, portanto atrasa em relação ao preço", "Não funciona em gráfico diário", "Precisa de volume alto"], "note": "Média móvel resume a tendência e serve de referência dinâmica; ela atrasa por construção e falha em mercado lateral."}, "narration": {"src": "/audio/journeys/trd-m2l1.mp3", "captionsSrc": "/audio/journeys/trd-m2l1.json", "transcript": "Médias móveis. A média móvel suaviza o ruído: em vez de cada candle, você vê o preço médio dos últimos períodos deslizando pelo gráfico. A simples pesa todos os períodos igualmente; a exponencial dá mais peso ao recente e reage mais rápido. Períodos curtos, como vinte e um, acompanham o movimento de perto; longos, como duzentos, mostram a maré de fundo — preço acima da média longa sugere ambiente comprador, abaixo, vendedor.\n\nEm tendências, médias funcionam como suporte e resistência dinâmicos: o preço recua até elas e reage, oferecendo pontos de interesse objetivos. Mas entenda a limitação de fábrica: toda média é calculada sobre o passado e sempre atrasa. Em mercado lateral, ela serpenteia pelo meio do preço e gera sinal falso atrás de sinal falso. Média móvel é régua de contexto, não botão de compra — combine-a com a estrutura que você aprendeu no módulo um.", "summary": "Média simples e exponencial, médias como referência dinâmica de tendência e o problema do atraso.", "duration": 63.072, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m2l2', '{"paragraphs": ["RSI e momentum. O índice de força relativa mede a velocidade do movimento numa escala de zero a cem, comparando a força das altas e das quedas recentes. Acima de setenta, convencionou-se dizer sobrecomprado; abaixo de trinta, sobrevendido. E aqui nasce o erro mais caro do iniciante: vender só porque marcou setenta. Em tendência forte, o RSI fica esticado por semanas enquanto o preço continua — sobrecomprado é descrição de força, não ordem de venda.", "A leitura mais rica são as divergências: o preço faz um topo mais alto, mas o RSI faz um topo mais baixo — o movimento avança com motor cada vez mais fraco. Divergências não datam a reversão, mas avisam para apertar a gestão. Use o RSI como medidor de contexto e combustível, subordinado à estrutura: primeiro tendência e níveis, depois o indicador. Nunca o contrário."], "takeaway": "RSI mede a velocidade do movimento; sobrecomprado não é sinal de venda em tendência forte — divergências valem mais que níveis.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Numa tendência de alta forte, o RSI passa de 70. O que isso significa?", "options": ["Venda imediata", "Apenas que o momentum é forte; em tendência, o RSI pode ficar esticado por muito tempo", "Reversão garantida em 3 candles", "Erro do indicador"], "note": "RSI mede a velocidade do movimento; sobrecomprado não é sinal de venda em tendência forte — divergências valem mais que níveis."}, "narration": {"src": "/audio/journeys/trd-m2l2.mp3", "captionsSrc": "/audio/journeys/trd-m2l2.json", "transcript": "RSI e momentum. O índice de força relativa mede a velocidade do movimento numa escala de zero a cem, comparando a força das altas e das quedas recentes. Acima de setenta, convencionou-se dizer sobrecomprado; abaixo de trinta, sobrevendido. E aqui nasce o erro mais caro do iniciante: vender só porque marcou setenta. Em tendência forte, o RSI fica esticado por semanas enquanto o preço continua — sobrecomprado é descrição de força, não ordem de venda.\n\nA leitura mais rica são as divergências: o preço faz um topo mais alto, mas o RSI faz um topo mais baixo — o movimento avança com motor cada vez mais fraco. Divergências não datam a reversão, mas avisam para apertar a gestão. Use o RSI como medidor de contexto e combustível, subordinado à estrutura: primeiro tendência e níveis, depois o indicador. Nunca o contrário.", "summary": "O que o índice de força relativa mede, os mitos do sobrecomprado/sobrevendido e divergências.", "duration": 62.112, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m2l3', '{"paragraphs": ["Confluência de sinais. Nenhuma ferramenta isolada tem vantagem suficiente — a vantagem nasce da coincidência. Confluência é quando fatores independentes apontam para a mesma decisão no mesmo lugar: a tendência de fundo é de alta; o preço recua a uma zona de suporte já testada; o volume seca no recuo, mostrando falta de convicção vendedora; um candle de rejeição confirma a reação; e o RSI sustenta a leitura sem divergência contrária.", "Cada fator soma probabilidade; três ou mais no mesmo ponto formam uma operação de qualidade. O efeito colateral é virtude: confluência filtra. A maior parte dos gráficos, na maior parte do tempo, não oferece nada — e a resposta profissional para nada é não operar. Defina por escrito quais confluências formam o seu setup e recuse tudo que não as cumpre. Trading lucrativo se parece muito mais com paciência do que com ação."], "takeaway": "Um sinal isolado é ruído; operação de qualidade nasce onde três ou mais fatores independentes coincidem.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Qual cenário tem mais confluência para compra?", "options": ["RSI em 28, sozinho, em queda livre", "Recuo a um suporte testado, em tendência de alta, com volume secando no recuo e pavio de rejeição na zona", "Rompimento sem volume", "Dica de influenciador com gráfico bonito"], "note": "Um sinal isolado é ruído; operação de qualidade nasce onde três ou mais fatores independentes coincidem."}, "narration": {"src": "/audio/journeys/trd-m2l3.mp3", "captionsSrc": "/audio/journeys/trd-m2l3.json", "transcript": "Confluência de sinais. Nenhuma ferramenta isolada tem vantagem suficiente — a vantagem nasce da coincidência. Confluência é quando fatores independentes apontam para a mesma decisão no mesmo lugar: a tendência de fundo é de alta; o preço recua a uma zona de suporte já testada; o volume seca no recuo, mostrando falta de convicção vendedora; um candle de rejeição confirma a reação; e o RSI sustenta a leitura sem divergência contrária.\n\nCada fator soma probabilidade; três ou mais no mesmo ponto formam uma operação de qualidade. O efeito colateral é virtude: confluência filtra. A maior parte dos gráficos, na maior parte do tempo, não oferece nada — e a resposta profissional para nada é não operar. Defina por escrito quais confluências formam o seu setup e recuse tudo que não as cumpre. Trading lucrativo se parece muito mais com paciência do que com ação.", "summary": "Montar operações onde estrutura, nível, volume e indicador apontam juntos — e descartar o resto.", "duration": 61.032, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m2l4', '{"paragraphs": ["Timeframes e o quadro maior. O mesmo mercado conta histórias diferentes em cada tempo gráfico: alta no diário, queda no quinze minutos — e as duas leituras estão certas, em escalas diferentes. Sem método, isso vira confusão; com método, vira precisão. O processo: comece de cima. No diário, defina a maré — tendência e zonas importantes. No intermediário, como o de quatro horas ou uma hora, acompanhe a onda até suas zonas. No menor, encontre o gatilho fino de entrada, com stop mais curto.", "Duas regras mantêm a sanidade. Primeira: o tempo maior manda — sinal do menor contra a maré do maior é sinal fraco. Segunda: analisou e entrou, gerencie no tempo gráfico do plano; descer para o um minuto para sofrer com cada oscilação só fabrica decisões ruins. Zoom out para decidir, zoom in para executar."], "takeaway": "Contexto no tempo maior, execução no menor; conflito entre tempos gráficos se resolve a favor do maior.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Qual sequência de análise multi-tempo é correta?", "options": ["Só o 1 minuto, para agilidade", "Contexto e níveis no diário/4h, gatilho e entrada no 1h/15min, sempre a favor do tempo maior", "Todos os tempos com peso igual", "O tempo gráfico não altera a análise"], "note": "Contexto no tempo maior, execução no menor; conflito entre tempos gráficos se resolve a favor do maior."}, "narration": {"src": "/audio/journeys/trd-m2l4.mp3", "captionsSrc": "/audio/journeys/trd-m2l4.json", "transcript": "Timeframes e o quadro maior. O mesmo mercado conta histórias diferentes em cada tempo gráfico: alta no diário, queda no quinze minutos — e as duas leituras estão certas, em escalas diferentes. Sem método, isso vira confusão; com método, vira precisão. O processo: comece de cima. No diário, defina a maré — tendência e zonas importantes. No intermediário, como o de quatro horas ou uma hora, acompanhe a onda até suas zonas. No menor, encontre o gatilho fino de entrada, com stop mais curto.\n\nDuas regras mantêm a sanidade. Primeira: o tempo maior manda — sinal do menor contra a maré do maior é sinal fraco. Segunda: analisou e entrou, gerencie no tempo gráfico do plano; descer para o um minuto para sofrer com cada oscilação só fabrica decisões ruins. Zoom out para decidir, zoom in para executar.", "summary": "Análise multi-tempo: decidir contexto no tempo maior e executar no menor, sem se perder no ruído.", "duration": 62.424, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m3l1', '{"paragraphs": ["Risco por operação. Aqui está o segredo aberto do trading: o que define quem sobrevive não é a taxa de acerto, é o tamanho da perda. A ferramenta é o risco fixo por operação — um percentual pequeno da conta, tipicamente um a dois por cento, que você aceita perder se o stop for atingido. A partir dele e da distância do stop, calcula-se o tamanho da posição, exatamente como toda operação profissional é dimensionada.", "A matemática explica o padrão. Sequências de perda são estatisticamente certas — qualquer método passa por elas. Dez perdas seguidas a um por cento deixam cerca de noventa por cento da conta: desconfortável, recuperável. A cinco por cento, sobra menos de sessenta; a dez, a conta praticamente acabou — e o buraco cresce mais rápido do que a capacidade de sair dele. Risco pequeno não é timidez: é a licença matemática para continuar no jogo tempo suficiente para a vantagem aparecer."], "takeaway": "Risco fixo e pequeno por operação é o que torna sequências de perda — inevitáveis — sobrevivíveis.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Arriscando 1% por operação, quanto resta da conta após 10 perdas seguidas (aprox.)?", "options": ["90%", "50%", "99%", "0%"], "note": "Risco fixo e pequeno por operação é o que torna sequências de perda — inevitáveis — sobrevivíveis."}, "narration": {"src": "/audio/journeys/trd-m3l1.mp3", "captionsSrc": "/audio/journeys/trd-m3l1.json", "transcript": "Risco por operação. Aqui está o segredo aberto do trading: o que define quem sobrevive não é a taxa de acerto, é o tamanho da perda. A ferramenta é o risco fixo por operação — um percentual pequeno da conta, tipicamente um a dois por cento, que você aceita perder se o stop for atingido. A partir dele e da distância do stop, calcula-se o tamanho da posição, exatamente como toda operação profissional é dimensionada.\n\nA matemática explica o padrão. Sequências de perda são estatisticamente certas — qualquer método passa por elas. Dez perdas seguidas a um por cento deixam cerca de noventa por cento da conta: desconfortável, recuperável. A cinco por cento, sobra menos de sessenta; a dez, a conta praticamente acabou — e o buraco cresce mais rápido do que a capacidade de sair dele. Risco pequeno não é timidez: é a licença matemática para continuar no jogo tempo suficiente para a vantagem aparecer.", "summary": "O percentual fixo de risco, por que 1–2% é o padrão e a matemática da sobrevivência.", "duration": 64.824, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m3l2', '{"paragraphs": ["Relação risco-retorno. Profissionais não medem operações em reais — medem em R, o valor arriscado. Perdeu no stop, menos um R. Ganhou o dobro do risco, mais dois R. Essa régua muda tudo, porque conecta duas variáveis: quanto você ganha quando acerta e com que frequência precisa acertar. Quem só busca alvos de um R precisa acertar bem mais da metade das vezes só para empatar com os custos. Quem opera alvos de dois R lucra acertando quatro em dez: quatro vitórias somam oito R, seis derrotas custam seis, saldo positivo de dois R.", "Por isso a disciplina de recusar operações de risco-retorno pobre importa tanto quanto a análise: o alvo realista precisa valer no mínimo o dobro do stop. E registre tudo em R no seu diário — é o único jeito honesto de saber se o seu método tem vantagem ou apenas sorte recente."], "takeaway": "Pense em R, não em dinheiro: com ganhos médios de 2R, você lucra acertando menos da metade das vezes.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Um trader acerta 40% das operações, perdendo 1R nas derrotas e ganhando 2R nas vitórias. O resultado a cada 10 trades é:", "options": ["Prejuízo de 2R", "Lucro de 2R", "Zero a zero", "Impossível calcular"], "note": "Pense em R, não em dinheiro: com ganhos médios de 2R, você lucra acertando menos da metade das vezes."}, "narration": {"src": "/audio/journeys/trd-m3l2.mp3", "captionsSrc": "/audio/journeys/trd-m3l2.json", "transcript": "Relação risco-retorno. Profissionais não medem operações em reais — medem em R, o valor arriscado. Perdeu no stop, menos um R. Ganhou o dobro do risco, mais dois R. Essa régua muda tudo, porque conecta duas variáveis: quanto você ganha quando acerta e com que frequência precisa acertar. Quem só busca alvos de um R precisa acertar bem mais da metade das vezes só para empatar com os custos. Quem opera alvos de dois R lucra acertando quatro em dez: quatro vitórias somam oito R, seis derrotas custam seis, saldo positivo de dois R.\n\nPor isso a disciplina de recusar operações de risco-retorno pobre importa tanto quanto a análise: o alvo realista precisa valer no mínimo o dobro do stop. E registre tudo em R no seu diário — é o único jeito honesto de saber se o seu método tem vantagem ou apenas sorte recente.", "summary": "Medir cada operação em múltiplos de risco (R) e a relação entre payoff e taxa de acerto.", "duration": 58.752, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m3l3', '{"paragraphs": ["Drawdown e recuperação. Drawdown é a queda entre o pico da conta e o fundo seguinte — e sua matemática é cruelmente assimétrica. Caiu dez por cento? Precisa de onze para voltar. Caiu trinta? Precisa de quarenta e três. Caiu cinquenta? Precisa dobrar a conta só para empatar. A lição: buracos rasos se escala, buracos fundos viram prisão. Todo o trabalho de gestão existe para manter o drawdown na zona recuperável.", "As ferramentas: limite de perda diário — bateu, fechou a plataforma, sem exceção; limite semanal, que impõe pausa maior; e redução de tamanho durante o vale — metade do risco até recuperar metade do buraco. O pior erro é o oposto instintivo: aumentar a mão para recuperar rápido, transformando um vale em cratera. Drawdown faz parte da profissão. Atravessá-lo pequeno, devagar e por protocolo é o que diferencia carreira de história triste."], "takeaway": "Perder 50% exige ganhar 100% para voltar; limites de perda automáticos existem para o drawdown nunca chegar lá.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Uma conta cai 50%. Quanto precisa render para voltar ao ponto inicial?", "options": ["50%", "75%", "100%", "25%"], "note": "Perder 50% exige ganhar 100% para voltar; limites de perda automáticos existem para o drawdown nunca chegar lá."}, "narration": {"src": "/audio/journeys/trd-m3l3.mp3", "captionsSrc": "/audio/journeys/trd-m3l3.json", "transcript": "Drawdown e recuperação. Drawdown é a queda entre o pico da conta e o fundo seguinte — e sua matemática é cruelmente assimétrica. Caiu dez por cento? Precisa de onze para voltar. Caiu trinta? Precisa de quarenta e três. Caiu cinquenta? Precisa dobrar a conta só para empatar. A lição: buracos rasos se escala, buracos fundos viram prisão. Todo o trabalho de gestão existe para manter o drawdown na zona recuperável.\n\nAs ferramentas: limite de perda diário — bateu, fechou a plataforma, sem exceção; limite semanal, que impõe pausa maior; e redução de tamanho durante o vale — metade do risco até recuperar metade do buraco. O pior erro é o oposto instintivo: aumentar a mão para recuperar rápido, transformando um vale em cratera. Drawdown faz parte da profissão. Atravessá-lo pequeno, devagar e por protocolo é o que diferencia carreira de história triste.", "summary": "A matemática assimétrica das perdas, limites de perda diários e o protocolo para atravessar vales.", "duration": 66.312, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m4l1', '{"paragraphs": ["Plano de trading. Sob pressão, com dinheiro na mesa, seu cérebro é péssimo conselheiro — o plano existe para decidir antes, com calma, o que você executaria depois, sob estresse. O documento tem cinco partes. Setups: as poucas situações exatas em que você opera, com confluências, gatilho, stop e alvo descritos. Risco: percentual por operação, limites diário e semanal, tamanho máximo. Rotina: quando você analisa, quando executa, quando o mercado fica desligado. Instrumentos e tempos gráficos: onde você joga. Revisão: quando e como o plano é reavaliado — em datas fixas, nunca no meio de uma sequência emocional.", "A regra de ouro cabe numa frase: se a operação não está descrita no plano, ela não existe. Comece simples — um setup, uma regra de risco, uma rotina. Plano simples e seguido vale infinitamente mais que plano perfeito e ignorado."], "takeaway": "O plano decide antes, com calma, o que você executaria depois, sob pressão; se não está no plano, não se opera.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Qual a função central de um plano de trading escrito?", "options": ["Prever o mercado", "Tirar decisões do calor do momento, definindo antes o que pode e o que não pode ser feito", "Garantir lucro mensal", "Substituir a análise"], "note": "O plano decide antes, com calma, o que você executaria depois, sob pressão; se não está no plano, não se opera."}, "narration": {"src": "/audio/journeys/trd-m4l1.mp3", "captionsSrc": "/audio/journeys/trd-m4l1.json", "transcript": "Plano de trading. Sob pressão, com dinheiro na mesa, seu cérebro é péssimo conselheiro — o plano existe para decidir antes, com calma, o que você executaria depois, sob estresse. O documento tem cinco partes. Setups: as poucas situações exatas em que você opera, com confluências, gatilho, stop e alvo descritos. Risco: percentual por operação, limites diário e semanal, tamanho máximo. Rotina: quando você analisa, quando executa, quando o mercado fica desligado. Instrumentos e tempos gráficos: onde você joga. Revisão: quando e como o plano é reavaliado — em datas fixas, nunca no meio de uma sequência emocional.\n\nA regra de ouro cabe numa frase: se a operação não está descrita no plano, ela não existe. Comece simples — um setup, uma regra de risco, uma rotina. Plano simples e seguido vale infinitamente mais que plano perfeito e ignorado.", "summary": "O documento que transforma conhecimento em regras operáveis: setups, risco, horários e revisão.", "duration": 66.84, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m4l2', '{"paragraphs": ["Diário de operações. A memória é editora: guarda os acertos épicos, apaga os erros repetidos. O diário é o corretivo. Para cada operação, registre o objetivo: data, ativo, setup do plano, entrada, stop, alvo, resultado em R. E registre o subjetivo, que é onde mora o ouro: seguiu o plano ou improvisou? Qual era o estado emocional — calmo, ansioso, vingativo? Um print do gráfico na entrada e na saída completa o retrato.", "A revisão semanal responde perguntas que o extrato não responde: qual setup realmente paga? Que horário concentra seus erros? Quanto custou, em R, cada quebra de disciplina? Padrões invisíveis no dia a dia ficam óbvios em vinte registros. Muitos traders descobrem no diário que seriam lucrativos apenas cortando as operações fora do plano. Quem não registra, opina sobre si mesmo; quem registra, sabe."], "takeaway": "O diário transforma experiência em dado: sem registro, você repete erros; com registro, você os identifica e corta.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Qual campo do diário mais ajuda a melhorar a execução?", "options": ["O lucro em reais", "Se a operação seguiu o plano e o estado emocional na entrada", "A opinião de terceiros", "O nome do candle"], "note": "O diário transforma experiência em dado: sem registro, você repete erros; com registro, você os identifica e corta."}, "narration": {"src": "/audio/journeys/trd-m4l2.mp3", "captionsSrc": "/audio/journeys/trd-m4l2.json", "transcript": "Diário de operações. A memória é editora: guarda os acertos épicos, apaga os erros repetidos. O diário é o corretivo. Para cada operação, registre o objetivo: data, ativo, setup do plano, entrada, stop, alvo, resultado em R. E registre o subjetivo, que é onde mora o ouro: seguiu o plano ou improvisou? Qual era o estado emocional — calmo, ansioso, vingativo? Um print do gráfico na entrada e na saída completa o retrato.\n\nA revisão semanal responde perguntas que o extrato não responde: qual setup realmente paga? Que horário concentra seus erros? Quanto custou, em R, cada quebra de disciplina? Padrões invisíveis no dia a dia ficam óbvios em vinte registros. Muitos traders descobrem no diário que seriam lucrativos apenas cortando as operações fora do plano. Quem não registra, opina sobre si mesmo; quem registra, sabe.", "summary": "O que registrar em cada trade, como revisar e como o diário revela seus padrões invisíveis.", "duration": 67.272, "voice": "pt-BR-AntonioNeural"}}'::jsonb),
  ('trd-m4l3', '{"paragraphs": ["Psicologia e disciplina. Você já tem o conhecimento técnico desta jornada inteira — e ele não vale nada nas mãos do seu pior estado emocional. Os sabotadores clássicos: o medo, que faz sair cedo demais dos lucros e hesitar nas melhores entradas; a ganância, que alarga alvos e tamanhos no meio do jogo; a esperança, que segura prejuízo esperando volta; e o tilt, o estado alterado pós-perda em que cada decisão nasce errada.", "A solução profissional não é virar um monge — é reduzir o espaço da emoção com engenharia. Decisões pré-definidas no plano. Stop e alvo enviados junto com a entrada. Limite diário que encerra o dia sozinho. Pausa obrigatória após duas perdas. Diário que expõe os padrões. Rotina de sono, tela e descanso levada a sério. A disciplina que funciona não é a heroica, é a estrutural. O mercado estará aí amanhã; seu trabalho é garantir que você também esteja."], "takeaway": "Não se vence a emoção com força de vontade, e sim com processo: regras automáticas, limites e pausas transformam psicologia em engenharia.", "sources": [], "exercise": {"title": "Confira seu entendimento", "prompt": "Qual a defesa mais eficaz contra o tilt (operar emocionalmente após perdas)?", "options": ["Meditar durante a operação", "Regras automáticas de pausa e limite diário de perda definidas antes", "Aumentar a mão para recuperar", "Trocar de ativo"], "note": "Não se vence a emoção com força de vontade, e sim com processo: regras automáticas, limites e pausas transformam psicologia em engenharia."}, "narration": {"src": "/audio/journeys/trd-m4l3.mp3", "captionsSrc": "/audio/journeys/trd-m4l3.json", "transcript": "Psicologia e disciplina. Você já tem o conhecimento técnico desta jornada inteira — e ele não vale nada nas mãos do seu pior estado emocional. Os sabotadores clássicos: o medo, que faz sair cedo demais dos lucros e hesitar nas melhores entradas; a ganância, que alarga alvos e tamanhos no meio do jogo; a esperança, que segura prejuízo esperando volta; e o tilt, o estado alterado pós-perda em que cada decisão nasce errada.\n\nA solução profissional não é virar um monge — é reduzir o espaço da emoção com engenharia. Decisões pré-definidas no plano. Stop e alvo enviados junto com a entrada. Limite diário que encerra o dia sozinho. Pausa obrigatória após duas perdas. Diário que expõe os padrões. Rotina de sono, tela e descanso levada a sério. A disciplina que funciona não é a heroica, é a estrutural. O mercado estará aí amanhã; seu trabalho é garantir que você também esteja.", "summary": "Os vieses que sabotam a execução — medo, ganância, tilt — e os sistemas que os neutralizam.", "duration": 65.76, "voice": "pt-BR-AntonioNeural"}}'::jsonb)
insert into public.module_quiz_questions (module_id, questions) values
  ('meme-m1', '[{"question": "O que diferencia uma memecoin de um token de utilidade?", "options": ["O blockchain onde foi criada", "O valor vem principalmente de atenção e comunidade, não de uso ou receita", "O preço unitário mais baixo", "A quantidade de holders"], "answer": 1, "explanation": "Memecoin é um ativo movido a atenção e comunidade, não a fluxo de caixa — o risco faz parte da definição."}, {"question": "Um token custa R$ 0,0001 com 100 trilhões de unidades em circulação. O que isso diz sobre ele estar \"barato\"?", "options": ["Está barato, o preço é baixo", "Nada — barato ou caro depende do market cap, não do preço unitário", "Está caro, porque tem muito supply", "Depende só do volume"], "answer": 1, "explanation": "Compare tokens por market cap e FDV, nunca pelo preço unitário; supply que ainda vai destravar é diluição futura."}, {"question": "Um token tem market cap de 10 milhões e pool de liquidez de 20 mil dólares. Qual o principal risco?", "options": ["Nenhum, o market cap é alto", "Vender qualquer posição relevante derruba o preço e você não sai pelo valor da tela", "O token pode ser clonado", "A taxa da DEX aumenta"], "answer": 1, "explanation": "O preço só é real se houver liquidez para sair; avalie o tamanho do pool antes do gráfico."}, {"question": "Qual sinal levanta suspeita de volume artificial?", "options": ["Volume alto com liquidez e holders crescendo juntos", "Volume gigante com pouquíssimos traders únicos e liquidez parada", "Volume caindo em fim de semana", "Volume maior na DEX do que na CEX"], "answer": 1, "explanation": "Volume e holders podem ser fabricados; procure consistência entre volume, liquidez e número de traders reais."}, {"question": "Num swap em uma DEX com AMM, você negocia contra:", "options": ["Outro trader com ordem oposta", "A equipe do token", "Um pool de liquidez, com preço definido pela proporção dos ativos", "O validador da rede"], "answer": 2, "explanation": "Na DEX você negocia contra um pool, não contra outra pessoa; slippage e taxa fazem parte de todo swap."}]'::jsonb),
  ('meme-m2', '[{"question": "Qual é o uso correto de um screener de tokens?", "options": ["Comprar os primeiros da lista de alta", "Filtrar candidatos por liquidez, idade e volume para depois investigar cada um", "Copiar as compras das carteiras maiores", "Achar tokens antes de terem liquidez"], "answer": 1, "explanation": "Screener serve para filtrar, não para decidir; todo token encontrado entra numa fila de investigação, não de compra."}, {"question": "O que significa a liquidez de um pool estar \"queimada\"?", "options": ["O token perdeu valor", "Os tokens de LP foram enviados para um endereço irrecuperável, impedindo a remoção do pool", "O pool foi hackeado", "A taxa do pool subiu"], "answer": 1, "explanation": "Liquidez destravada é porta de saída para o criador; procure lock longo ou burn e proporção razoável entre pool e market cap."}, {"question": "O que é um honeypot?", "options": ["Um token com taxa alta", "Um contrato que permite comprar, mas impede ou inviabiliza a venda", "Um pool sem liquidez", "Um token sem site"], "answer": 1, "explanation": "Antes de comprar, cheque se o contrato permite mint, bloqueio de venda ou mudança de taxas — e se a propriedade foi renunciada."}, {"question": "Os dez maiores holders de um token concentram 60% do supply e várias carteiras foram financiadas pela mesma origem. Isso indica:", "options": ["Comunidade forte", "Alto risco de controle por um grupo e despejo coordenado", "Liquidez saudável", "Token institucional"], "answer": 1, "explanation": "Concentração alta em poucas carteiras conectadas é o padrão que antecede despejo; leia o supply antes do gráfico."}, {"question": "Qual sinal sugere comunidade orgânica?", "options": ["Milhares de respostas idênticas com emojis de foguete", "Grupos com conversa real, piadas próprias, críticas e criadores de conteúdo espontâneos", "Seguidores comprados crescendo de mil em mil", "Promessa de listagem em corretora"], "answer": 1, "explanation": "Comunidade real conversa, cria e discorda; engajamento comprado só repete. Narrativa forte tem contexto cultural, não só promessa de alta."}]'::jsonb),
  ('meme-m3', '[{"question": "Por que usar uma carteira dedicada para memecoins?", "options": ["As taxas ficam menores", "Limita o dano de aprovações maliciosas e golpes ao capital de risco, protegendo o patrimônio principal", "O slippage diminui", "É exigência das DEXs"], "answer": 1, "explanation": "Opere memecoins com uma carteira separada e capital limitado; nunca use a carteira de custódia principal."}, {"question": "Qual prática melhora a consistência em memecoins?", "options": ["Comprar mais quando cai para baixar o preço médio", "Definir antes da entrada os pontos de realização parcial e de abandono da tese", "Segurar até voltar ao topo", "Entrar all-in em sinais de grupo"], "answer": 1, "explanation": "Escreva antes da compra: por que entrar, quanto, onde sair no lucro e no prejuízo — e execute realização parcial."}, {"question": "O que é um ataque sandwich?", "options": ["Comprar em duas DEXs ao mesmo tempo", "Um robô compra antes da sua ordem e vende logo depois, empurrando seu preço de execução", "Dividir a ordem em três partes", "Uma taxa cobrada pela rede"], "answer": 1, "explanation": "Slippage alto demais convida ataque sandwich; use o mínimo que executa e desconfie de tokens que exigem tolerância enorme."}, {"question": "Qual estrutura de banca é coerente com memecoins?", "options": ["50% do patrimônio em um token promissor", "Capital de risco isolado, dividido em posições pequenas, assumindo que cada uma pode ir a zero", "Usar alavancagem para compensar posições pequenas", "Média a mercado sem limite"], "answer": 1, "explanation": "Posições pequenas e numerosas, banca isolada e a premissa de que qualquer token pode ir a zero a qualquer momento."}]'::jsonb),
  ('meme-m4', '[{"question": "O que caracteriza um soft rug?", "options": ["A liquidez é drenada num bloco", "A equipe vende gradualmente e abandona o projeto enquanto mantém aparência de atividade", "O contrato bloqueia vendas", "A rede fica congestionada"], "answer": 1, "explanation": "Rug duro drena a liquidez de uma vez; soft rug mata por abandono e venda gradual dos insiders — os sinais aparecem on-chain antes."}, {"question": "Você recebe um airdrop desconhecido que pede para \"resgatar\" num site. Qual a atitude correta?", "options": ["Resgatar rápido antes que expire", "Ignorar: interagir pode acionar aprovações que drenam a carteira", "Transferir o airdrop para a carteira principal", "Vender imediatamente na DEX"], "answer": 1, "explanation": "A maior parte das perdas vem de assinatura e aprovação dadas ao contrato errado; confira origem, domínio e o que exatamente você está assinando."}, {"question": "Um token passa em tudo, exceto: o LP está destravado. O que fazer?", "options": ["Entrar com posição menor", "Não entrar — porta de saída aberta para o criador invalida o resto", "Entrar e monitorar o LP", "Esperar o preço cair"], "answer": 1, "explanation": "Contrato, liquidez, holders, comunidade, plano e tamanho: se qualquer etapa falhar, a resposta padrão é não entrar."}]'::jsonb),
  ('fut-m1', '[{"question": "Qual a principal diferença entre comprar BTC à vista e abrir long em BTC perpétuo?", "options": ["Nenhuma, o preço é o mesmo", "No perpétuo você tem um contrato com margem, funding e risco de liquidação, sem possuir o ativo", "O perpétuo não tem taxas", "O spot é mais arriscado"], "answer": 1, "explanation": "No perpétuo você opera um contrato indexado ao preço, sem vencimento e sem possuir o ativo — com riscos próprios que o spot não tem."}, {"question": "Por que o short tem perfil de risco diferente do long?", "options": ["Porque paga mais taxa", "Porque a queda é limitada a 100%, mas a alta contra o short não tem teto", "Porque a corretora limita shorts", "Não há diferença"], "answer": 1, "explanation": "Long lucra na alta, short lucra na queda; o short tem risco assimétrico porque a alta não tem teto."}, {"question": "Com 10x de alavancagem e margem isolada, aproximadamente que movimento contra a posição consome toda a margem?", "options": ["50%", "20%", "~10%", "1%"], "answer": 2, "explanation": "Alavancagem multiplica exposição, não acerto; margem isolada limita o dano por posição, cruzada arrisca a conta inteira."}, {"question": "O funding está fortemente positivo há dias. O que isso indica?", "options": ["O mercado está vendido e shorts pagam longs", "O mercado está comprado e alavancado; longs pagam para manter posição, sinal de euforia", "A corretora aumentou taxas", "Nada relevante"], "answer": 1, "explanation": "Funding positivo: longs pagam shorts; negativo: shorts pagam longs. Funding extremo revela desequilíbrio e custo real de carregar posição."}]'::jsonb),
  ('fut-m2', '[{"question": "Para que serve a opção reduce-only num stop?", "options": ["Reduzir a taxa da ordem", "Garantir que a ordem só diminua a posição existente, nunca abra uma nova na direção oposta", "Reduzir o slippage", "Reduzir a alavancagem"], "answer": 1, "explanation": "Ordem limitada controla preço, ordem a mercado garante execução; reduce-only garante que a proteção nunca vira posição nova."}, {"question": "Por que as corretoras usam preço de marca em vez do último negócio para liquidar?", "options": ["Para lucrar mais", "Para evitar liquidações causadas por manipulação momentânea do último preço no próprio livro", "Porque é mais rápido", "Exigência regulatória"], "answer": 1, "explanation": "A liquidação usa o preço de marca e consome sua margem com taxas punitivas; stop próprio existe para você nunca conhecê-la."}, {"question": "Onde deve ficar o stop de uma operação?", "options": ["A uma distância fixa de 2% sempre", "No ponto em que a análise que motivou a entrada deixa de ser válida", "O mais longe possível para não ser ativado", "Não usar stop para evitar manipulação"], "answer": 1, "explanation": "O stop fica onde a tese morre, não onde a dor aperta; alvo e stop entram junto com a posição, nunca depois."}, {"question": "Conta de 10.000, risco de 1% por trade, stop a 4% da entrada. Qual o tamanho correto da posição?", "options": ["10.000", "100", "2.500", "40.000"], "answer": 2, "explanation": "Primeiro o risco em dinheiro, depois a distância do stop, e só então o tamanho; a alavancagem é consequência, não ponto de partida."}]'::jsonb),
  ('fut-m3', '[{"question": "O que é um short squeeze?", "options": ["Uma queda lenta e contínua", "Alta rápida forçada pela liquidação em cascata de posições vendidas", "Um tipo de ordem", "Redução de taxas para shorts"], "answer": 1, "explanation": "Opere padrões apenas dentro de contexto favorável; em mercado alavancado, rompimentos falsos e squeezes são a regra, não a exceção."}, {"question": "Você tem 1 BTC em carteira própria e quer proteção para um evento de risco sem vender. O que faz sentido avaliar?", "options": ["Long alavancado em BTC", "Short de tamanho equivalente em BTC perpétuo, considerando custo de funding e margem", "Comprar uma memecoin", "Aumentar a alavancagem"], "answer": 1, "explanation": "Hedge troca risco de preço por custo de funding e risco operacional; é seguro temporário, não estratégia permanente."}, {"question": "Após duas perdas seguidas, o trader dobra o tamanho para \"recuperar rápido\". Como se chama esse padrão e qual o resultado provável?", "options": ["Gestão agressiva; recuperação", "Martingale/revenge trading; risco crescente até a ruína", "Hedge dinâmico; neutro", "Scaling; lucro maior"], "answer": 1, "explanation": "Contas não morrem por uma análise errada, morrem por indisciplina repetida; reconheça os padrões em você antes que o extrato os mostre."}, {"question": "O que um plano de trade minimamente completo contém?", "options": ["Apenas as moedas favoritas", "Setups permitidos, risco por trade, limite de perda, rotina e critérios de revisão", "Metas de lucro diário obrigatórias", "Os sinais de um grupo pago"], "answer": 1, "explanation": "Se não está escrito, não é plano — é humor; opere apenas o que o documento autoriza e revise-o em datas fixas."}]'::jsonb),
  ('trd-m1', '[{"question": "Um candle com pavio inferior longo e corpo pequeno no topo, após uma queda, sugere:", "options": ["Continuação da queda", "Compradores rejeitaram preços mais baixos; possível exaustão vendedora", "Nada, pavios são aleatórios", "Aumento de taxa"], "answer": 1, "explanation": "Candle é registro de batalha: corpo mostra quem venceu, pavios mostram onde houve rejeição — sempre leia no contexto, nunca isolado."}, {"question": "Um suporte é rompido com força. O que costuma acontecer com esse nível?", "options": ["Deixa de importar", "Tende a virar resistência quando o preço retorna a ele", "Vira suporte mais forte", "O gráfico é invalidado"], "answer": 1, "explanation": "Suporte e resistência são zonas, não linhas exatas; a reação do preço na zona vale mais que a zona em si."}, {"question": "O que caracteriza uma tendência de alta?", "options": ["Preço acima da média de 200", "Sequência de topos e fundos ascendentes", "Volume alto", "RSI acima de 50"], "answer": 1, "explanation": "Tendência de alta = topos e fundos ascendentes; ela vale até a estrutura quebrar. Operar contra tendência é pagar para nadar contra a maré."}, {"question": "O preço rompe uma resistência importante com volume muito abaixo da média. Como interpretar?", "options": ["Rompimento confiável", "Rompimento suspeito, com risco elevado de ser falso", "Sinal de venda imediata", "O volume não importa em rompimentos"], "answer": 1, "explanation": "Movimento com volume tem participação real; rompimento sem volume é suspeito por padrão."}]'::jsonb),
  ('trd-m2', '[{"question": "Qual a limitação estrutural de toda média móvel?", "options": ["Só funciona em cripto", "É calculada sobre o passado, portanto atrasa em relação ao preço", "Não funciona em gráfico diário", "Precisa de volume alto"], "answer": 1, "explanation": "Média móvel resume a tendência e serve de referência dinâmica; ela atrasa por construção e falha em mercado lateral."}, {"question": "Numa tendência de alta forte, o RSI passa de 70. O que isso significa?", "options": ["Venda imediata", "Apenas que o momentum é forte; em tendência, o RSI pode ficar esticado por muito tempo", "Reversão garantida em 3 candles", "Erro do indicador"], "answer": 1, "explanation": "RSI mede a velocidade do movimento; sobrecomprado não é sinal de venda em tendência forte — divergências valem mais que níveis."}, {"question": "Qual cenário tem mais confluência para compra?", "options": ["RSI em 28, sozinho, em queda livre", "Recuo a um suporte testado, em tendência de alta, com volume secando no recuo e pavio de rejeição na zona", "Rompimento sem volume", "Dica de influenciador com gráfico bonito"], "answer": 1, "explanation": "Um sinal isolado é ruído; operação de qualidade nasce onde três ou mais fatores independentes coincidem."}, {"question": "Qual sequência de análise multi-tempo é correta?", "options": ["Só o 1 minuto, para agilidade", "Contexto e níveis no diário/4h, gatilho e entrada no 1h/15min, sempre a favor do tempo maior", "Todos os tempos com peso igual", "O tempo gráfico não altera a análise"], "answer": 1, "explanation": "Contexto no tempo maior, execução no menor; conflito entre tempos gráficos se resolve a favor do maior."}]'::jsonb),
  ('trd-m3', '[{"question": "Arriscando 1% por operação, quanto resta da conta após 10 perdas seguidas (aprox.)?", "options": ["90%", "50%", "99%", "0%"], "answer": 0, "explanation": "Risco fixo e pequeno por operação é o que torna sequências de perda — inevitáveis — sobrevivíveis."}, {"question": "Um trader acerta 40% das operações, perdendo 1R nas derrotas e ganhando 2R nas vitórias. O resultado a cada 10 trades é:", "options": ["Prejuízo de 2R", "Lucro de 2R", "Zero a zero", "Impossível calcular"], "answer": 1, "explanation": "Pense em R, não em dinheiro: com ganhos médios de 2R, você lucra acertando menos da metade das vezes."}, {"question": "Uma conta cai 50%. Quanto precisa render para voltar ao ponto inicial?", "options": ["50%", "75%", "100%", "25%"], "answer": 2, "explanation": "Perder 50% exige ganhar 100% para voltar; limites de perda automáticos existem para o drawdown nunca chegar lá."}]'::jsonb),
  ('trd-m4', '[{"question": "Qual a função central de um plano de trading escrito?", "options": ["Prever o mercado", "Tirar decisões do calor do momento, definindo antes o que pode e o que não pode ser feito", "Garantir lucro mensal", "Substituir a análise"], "answer": 1, "explanation": "O plano decide antes, com calma, o que você executaria depois, sob pressão; se não está no plano, não se opera."}, {"question": "Qual campo do diário mais ajuda a melhorar a execução?", "options": ["O lucro em reais", "Se a operação seguiu o plano e o estado emocional na entrada", "A opinião de terceiros", "O nome do candle"], "answer": 1, "explanation": "O diário transforma experiência em dado: sem registro, você repete erros; com registro, você os identifica e corta."}, {"question": "Qual a defesa mais eficaz contra o tilt (operar emocionalmente após perdas)?", "options": ["Meditar durante a operação", "Regras automáticas de pausa e limite diário de perda definidas antes", "Aumentar a mão para recuperar", "Trocar de ativo"], "answer": 1, "explanation": "Não se vence a emoção com força de vontade, e sim com processo: regras automáticas, limites e pausas transformam psicologia em engenharia."}]'::jsonb)
